window.LIBRARY=[{"id":"ronpyo-points","group":"論理・表現 第11〜13章（12月期末）","title":"論表 文法ルール（第11〜13章）","subject":"論理・表現","order":1,"version":3,"cards":[{"id":"c01","category":"〜ほど…ない","front":"「この本はあの本ほどおもしろくない。」\n英語にすると？","options":["This book is not as interesting as that one.","This book is not as more interesting as that one.","This book is not interesting as that one.","This book is not as interesting than that one."],"answer":0,"back":"答え：This book is not as interesting as that one.\nコツ：「〜ほど…ない」は not as ＿ as。2つ目も as（than にしない）\n（本冊376）"},{"id":"c02","category":"〜倍","front":"「私の部屋は弟の部屋の3倍広い。」\n英語にすると？","options":["My room is three times as larger as my brother's.","My room is as large three times as my brother's.","My room is three times as large as my brother's.","My room is three times as large than my brother's."],"answer":2,"back":"答え：My room is three times as large as my brother's.\nコツ：「3倍」は three times as ＿ as。2倍は twice、半分は half\n（本冊378〜381）"},{"id":"c03","category":"〜倍（大きさ・重さで言う）","front":"「この箱はあの箱の半分の大きさだ。」\nsize を使って英語にすると？","options":["This box is half the size of that one.","This box is the half size of that one.","This box is half the size than that one.","This box is half as size as that one."],"answer":0,"back":"答え：This box is half the size of that one.\nコツ：「半分の大きさ」は half the size of。重さなら the weight of\n（本冊382〜383）"},{"id":"c04","category":"同じだけ（お金・数）","front":"「私は兄と同じだけお金を持っている。」\n英語にすると？","options":["I have as many money as my brother.","I have as money much as my brother.","I have as much money than my brother.","I have as much money as my brother."],"answer":3,"back":"答え：I have as much money as my brother.\nコツ：お金は数えないので much。much money はくっつけて as と as ではさむ\n（本冊377）"},{"id":"c05","category":"できるだけ","front":"「できるだけ早く返事をください。」\npossible を使って英語にすると？","options":["Please reply as sooner as possible.","Please reply as soon than possible.","Please reply as soon as possible.","Please reply the soonest as possible."],"answer":2,"back":"答え：Please reply as soon as possible.\nコツ：「できるだけ〜」は as ＿ as possible。-er の形にしない\n（本冊384〜385）"},{"id":"c06","category":"〜というよりむしろ","front":"He is not so much a teacher as a friend.\nどういう意味？","options":["彼は友だちというより、むしろ先生だ。","彼は先生というより、むしろ友だちだ。","彼は先生ほど多くの友だちがいない。","彼は先生でもないし、友だちでもない。"],"answer":1,"back":"答え：彼は先生というより、むしろ友だちだ。\nコツ：not so much ＿ as 〜 は「＿というより〜」。後ろの方が本当\n（本冊386）"},{"id":"c07","category":"〜さえしない","front":"She left without so much as saying goodbye.\nどういう意味？","options":["彼女はたくさんさようならを言って去った。","彼女はさようならさえ言わずに去った。","彼女はさようならを言ってから去った。","彼女はさようならを言わずに、ここに残った。"],"answer":1,"back":"答え：彼女はさようならさえ言わずに去った。\nコツ：without so much as ＿ は「＿さえしないで」\n（本冊387〜388）"},{"id":"c08","category":"だれにも負けない","front":"He is as great a singer as ever lived.\nどういう意味？","options":["彼は昔、すごい歌手として生きていた。","彼はずっと長生きしている歌手だ。","彼は昔の歌手と同じくらい、ふつうの歌手だ。","彼は今までにいないほどすごい歌手だ。"],"answer":3,"back":"答え：彼は今までにいないほどすごい歌手だ。\nコツ：as ＿ as ever lived は「今までにいないほど＿」\n（本冊389〜390）"},{"id":"c09","category":"〜も（多い）","front":"「そのコンサートには5万人もの人が来た。」\n英語にすると？","options":["As many as 50,000 people came to the concert.","As much as 50,000 people came to the concert.","As many 50,000 people as came to the concert.","As more as 50,000 people came to the concert."],"answer":0,"back":"答え：As many as 50,000 people came to the concert.\nコツ：人の数が多くて「〜も」は as many as。お金・時間なら as much as\n（本冊391）"},{"id":"c10","category":"たった〜（少ない）","front":"「このシャツはたった4ドルだった。」\nas を使って英語にすると？","options":["This shirt cost as less as four dollars.","This shirt cost as little as four dollars.","This shirt cost as little than four dollars.","This shirt cost as many as four dollars."],"answer":1,"back":"答え：This shirt cost as little as four dollars.\nコツ：お金の「たった」は as little as。as many as は「〜も（多い）」で反対\n（本冊392）"},{"id":"c11","category":"早くも〜に","front":"Snow fell as early as October.\nどういう意味？","options":["10月より前に、一度だけ雪が降った。","10月になってもまだ雪が降った。","早くも10月に雪が降った。","10月のはじめにだけ雪が降った。"],"answer":2,"back":"答え：早くも10月に雪が降った。\nコツ：as early as ＿ は「早くも＿に」。as late as ＿ は「＿になってもまだ」\n（本冊393）"},{"id":"c12","category":"ずっと〜（強める）","front":"「今日は昨日よりずっと寒い。」\n英語にすると？","options":["Today is very colder than yesterday.","Today is much cold than yesterday.","Today is much more colder than yesterday.","Today is much colder than yesterday."],"answer":3,"back":"答え：Today is much colder than yesterday.\nコツ：「ずっと」は much を colder の前に。very は使えない\n（本冊394）"},{"id":"c13","category":"〜ほど…ない（less）","front":"「この車はあの車ほど高くない。」\nless を使って英語にすると？","options":["This car is less expensive as that one.","This car is less expensive than that one.","This car is less expensiver than that one.","This car is expensive less than that one."],"answer":1,"back":"答え：This car is less expensive than that one.\nコツ：not as ＿ as は less ＿ than と言いかえられる\n（本冊395）"},{"id":"c14","category":"〜というよりむしろ","front":"「彼は怒っているというより、むしろ悲しんでいる。」\n英語にすると？","options":["He is sadder than angry.","He is more sadder than angry.","He is more angry than sad.","He is more sad than angry."],"answer":3,"back":"答え：He is more sad than angry.\nコツ：同じ人の2つの様子をくらべるときは more ＿ than。sadder にしない\n（本冊396）"},{"id":"c15","category":"〜倍","front":"「この橋はあの橋の3倍長い。」\nlonger を使って英語にすると？","options":["This bridge is three times longer than that one.","This bridge is longer three times than that one.","This bridge is three times longer as that one.","This bridge is three times long than that one."],"answer":0,"back":"答え：This bridge is three times longer than that one.\nコツ：three times を longer の前に置くだけ\n（本冊397）"},{"id":"c16","category":"2つのうちの〜なほう","front":"「2人のうちで、ケンのほうが背が高い。」\n英語にすると？","options":["Ken is taller of the two.","Ken is the taller of the two.","Ken is the taller than the two.","Ken is the tall of the two."],"answer":1,"back":"答え：Ken is the taller of the two.\nコツ：「2人のうちで〜なほう」は the ＿er of the two。the を忘れない\n（本冊398）"},{"id":"c17","category":"〜すればするほど","front":"「たくさん練習すればするほど、うまくなる。」\n英語にすると？","options":["The more you practice, the good you get.","The more you practice, the better you get.","More you practice, better you get.","The more you practice, you get the better."],"answer":1,"back":"答え：The more you practice, the better you get.\nコツ：「〜すればするほど」は The ＿er …, the ＿er …。the を2回\n（本冊399〜400）"},{"id":"c18","category":"〜なのでいっそう","front":"I like him all the better for his honesty.\nどういう意味？","options":["彼は正直だが、私はあまり彼が好きではない。","私は彼の正直さより、ほかの所が好きだ。","彼が正直になれば、もっと好きになるだろう。","彼が正直なので、私はいっそう彼が好きだ。"],"answer":3,"back":"答え：彼が正直なので、私はいっそう彼が好きだ。\nコツ：all the ＿er for 〜 は「〜なので、いっそう＿」\n（本冊401）"},{"id":"c19","category":"〜なのに少しも…ない","front":"He is none the happier for his money.\nどういう意味？","options":["彼はお金がないので、少しも幸せではない。","彼はお金があるので、とても幸せだ。","彼はお金があるのに、少しも幸せではない。","彼はだれよりもお金があって幸せだ。"],"answer":2,"back":"答え：彼はお金があるのに、少しも幸せではない。\nコツ：none the ＿er for 〜 は「〜なのに少しも＿ない」\n（本冊402）"},{"id":"c20","category":"たった〜／〜も","front":"I have no more than 500 yen.\nどういう意味？","options":["私は500円しか持っていない。","私は500円より多く持っている。","私は500円も持っている。","私はもう500円は持っていない。"],"answer":0,"back":"答え：私は500円しか持っていない。\nコツ：no more than ＝「たった」。no less than は「〜も（多い！）」\n（本冊405〜406）"},{"id":"c21","category":"多くても／少なくとも","front":"The trip will cost not more than 3,000 yen.\nどういう意味？","options":["その旅行は、少なくとも3000円はかかる。","その旅行は、3000円よりずっと多くかかる。","その旅行は、もう3000円はかからない。","その旅行は、多くても3000円しかかからない。"],"answer":3,"back":"答え：その旅行は、多くても3000円しかかからない。\nコツ：not more than ＝「多くても」。not less than ＝「少なくとも」"},{"id":"c22","category":"〜でないのと同じ","front":"A bat is no more a bird than a dog is.\nどういう意味？","options":["コウモリが鳥でないのは、犬が鳥でないのと同じだ。","コウモリは、犬よりもずっと鳥に近い生き物だ。","コウモリは鳥の仲間だが、犬は鳥ではない。","コウモリも犬も、もう今は鳥ではなくなった。"],"answer":0,"back":"答え：コウモリが鳥でないのは、犬が鳥でないのと同じだ。\nコツ：no more 〜 than … は「…と同じで、まったく〜ではない」\n（本冊407）"},{"id":"c23","category":"〜でないのと同じ","front":"「イルカが魚でないのは、ネコが魚でないのと同じだ。」\nnot と any more を使って英語にすると？","options":["A dolphin is not a fish any more as a cat is.","A dolphin is not a fish more any than a cat is.","A dolphin is not a fish any more than a cat are.","A dolphin is not a fish any more than a cat is."],"answer":3,"back":"答え：A dolphin is not a fish any more than a cat is.\nコツ：no more を not … any more に分けて置くだけ\n（本冊408）"},{"id":"c24","category":"〜に負けないくらい","front":"She is no less kind than her mother is.\nどういう意味？","options":["彼女はお母さんほどやさしくない。","彼女はお母さんに負けないくらいやさしい。","彼女はやさしいが、お母さんはやさしくない。","彼女はもうお母さんにやさしくない。"],"answer":1,"back":"答え：彼女はお母さんに負けないくらいやさしい。\nコツ：no less ＿ than 〜 は「〜に負けないくらい＿だ」\n（本冊409）"},{"id":"c25","category":"決まった言い方","front":"He knows better than to play games before a test.\nどういう意味？","options":["彼はテストの前にゲームをするのがいちばん好きだ。","彼はテストの前にゲームをしたほうがいいと知っている。","彼はテストの前にゲームをするほどばかではない。","彼はテストよりもゲームのほうがずっと得意だ。"],"answer":2,"back":"答え：彼はテストの前にゲームをするほどばかではない。\nコツ：know better than to ＿ は「＿するほどばかじゃない」\n（本冊410〜411）"},{"id":"c26","category":"まして〜ない","front":"「私はピアノをひけない。まして教えることなんてできない。」\n英語にすると？","options":["I can't play the piano, much more teach it.","I can't play the piano, less much teach it.","I can't play the piano, much less teach it.","I can play the piano, much less teach it."],"answer":2,"back":"答え：I can't play the piano, much less teach it.\nコツ：「まして〜ない」は「〜ない」の文のあとに , much less 〜\n（本冊412）"},{"id":"c27","category":"もう〜ない","front":"「彼はもうここに住んでいない。」\nno longer を使って英語にすると？","options":["He no longer lives here.","He no longer doesn't live here.","He no longer live here.","He lives here no long."],"answer":0,"back":"答え：He no longer lives here.\nコツ：「もう〜ない」は no longer。not はもう入れない\n（本冊413）"},{"id":"c28","category":"than のかわりに to","front":"「このカメラはあのカメラより優れている。」\nsuperior を使って英語にすると？","options":["This camera is superior than that one.","This camera is more superior than that one.","This camera is superior as that one.","This camera is superior to that one."],"answer":3,"back":"答え：This camera is superior to that one.\nコツ：superior（優れた）は than でなく to。inferior・senior・junior も to\n（本冊414・416）"},{"id":"c29","category":"〜より…が好き","front":"「私はコーヒーより紅茶のほうが好きだ。」\nprefer を使って英語にすると？","options":["I prefer tea than coffee.","I prefer coffee to tea.","I prefer tea from coffee.","I prefer tea to coffee."],"answer":3,"back":"答え：I prefer tea to coffee.\nコツ：prefer ＿ to 〜 で「〜より＿が好き」。好きな方が先。than は使わない\n（本冊415）"},{"id":"c30","category":"いちばん（in と of）","front":"「ケンはクラスでいちばん背が高い。」\n英語にすると？","options":["Ken is the tallest of the class.","Ken is the tallest in the class.","Ken is the taller in the class.","Ken is the most tallest in the class."],"answer":1,"back":"答え：Ken is the tallest in the class.\nコツ：クラスなど場所・グループは in。「3人の中で」のような人数なら of\n（本冊417）"},{"id":"c31","category":"断然いちばん","front":"「富士山は日本で断然いちばん高い山だ。」\nby far を使って英語にすると？","options":["Mt. Fuji is the by far highest mountain in Japan.","Mt. Fuji is by far the highest mountain in Japan.","Mt. Fuji is very the highest mountain in Japan.","Mt. Fuji is by far the higher mountain in Japan."],"answer":1,"back":"答え：Mt. Fuji is by far the highest mountain in Japan.\nコツ：「断然いちばん」は by far the ＿est。by far は the の前\n（本冊418〜419）"},{"id":"c32","category":"2番目に〜","front":"「ケンはクラスで2番目に背が高い。」\n英語にすると？","options":["Ken is the second tallest in the class.","Ken is the tallest second in the class.","Ken is second the tallest in the class.","Ken is the second taller in the class."],"answer":0,"back":"答え：Ken is the second tallest in the class.\nコツ：「2番目に〜」は the second ＿est\n（本冊420）"},{"id":"c33","category":"いちばん〜な…の1つ","front":"「彼は日本でいちばん有名な歌手の1人だ。」\n英語にすると？","options":["He is one of the most famous singer in Japan.","He is one of most famous singers in Japan.","He is one of the famousest singers in Japan.","He is one of the most famous singers in Japan."],"answer":3,"back":"答え：He is one of the most famous singers in Japan.\nコツ：「〜の1人」は one of the most ＿ ＿s。最後に s（singers）\n（本冊421）"},{"id":"c34","category":"今までで一番","front":"「こんなにいい映画は見たことがない。」\nThis is で始めて英語にすると？","options":["This is the best movie I have ever seen.","This is the best movie I have never seen.","This is the better movie I have ever seen.","This is the best movie I have ever see."],"answer":0,"back":"答え：This is the best movie I have ever seen.\nコツ：「今まで〜した中でいちばん」は the best … I have ever ＿\n（本冊422〜423）"},{"id":"c35","category":"少なくとも／多くても","front":"「少なくとも1日1時間は勉強しなさい。」\n英語にすると？","options":["Study for at most one hour a day.","Study for at little one hour a day.","Study for the least one hour a day.","Study for at least one hour a day."],"answer":3,"back":"答え：Study for at least one hour a day.\nコツ：「少なくとも」は at least。「多くても」は at most\n（本冊424）"},{"id":"c36","category":"ほかのだれも〜ない","front":"「クラスのほかのだれもケンほど背が高くない。」\nNo other で始めて英語にすると？","options":["No other students in the class is as tall as Ken.","No other student in the class is as tall than Ken.","No other student in the class is as tall as Ken.","No other student in the class is not as tall as Ken."],"answer":2,"back":"答え：No other student in the class is as tall as Ken.\nコツ：No other student（s を付けない）。not は入れない\n（本冊425・427）"},{"id":"c37","category":"〜ほど…なものはない","front":"「健康ほど大切なものはない。」\nNothing で始めて英語にすると？","options":["Nothing is as important than health.","Nothing is not as important as health.","Nothing is as important as health.","Nothing is as more important as health."],"answer":2,"back":"答え：Nothing is as important as health.\nコツ：「〜ほど…なものはない」は Nothing is as ＿ as 〜\n（本冊426・428）"},{"id":"c38","category":"ほかのどの〜よりも","front":"「富士山は日本のほかのどの山よりも高い。」\nany other を使って英語にすると？","options":["Mt. Fuji is higher than any other mountains in Japan.","Mt. Fuji is higher than any mountain other in Japan.","Mt. Fuji is high than any other mountain in Japan.","Mt. Fuji is higher than any other mountain in Japan."],"answer":3,"back":"答え：Mt. Fuji is higher than any other mountain in Japan.\nコツ：any other のあとは1つの形（mountain、s を付けない）\n（本冊429〜430）"},{"id":"c39","category":"is・are などの形を合わせる","front":"「トムもケンもサッカーが好きだ。」\nboth を使って英語にすると？","options":["Both Tom and Ken like soccer.","Both Tom and Ken likes soccer.","Both Tom or Ken like soccer.","Tom both and Ken like soccer."],"answer":0,"back":"答え：Both Tom and Ken like soccer.\nコツ：both ＿ and 〜 は「2人」なので like（likes にしない）\n（本冊431）"},{"id":"c40","category":"is・are などの形を合わせる","front":"「ケンか私のどちらかがまちがっている。」\neither を使って英語にすると？","options":["Either Ken or I is wrong.","Either Ken or I are wrong.","Either Ken or I am wrong.","Either Ken and I am wrong."],"answer":2,"back":"答え：Either Ken or I am wrong.\nコツ：am / is / are は or のすぐ後ろ（I）に合わせる → am\n（本冊432〜434）"},{"id":"c41","category":"is・are などの形を合わせる","front":"「生徒たちだけでなく、先生も疲れていた。」\nas well as を使って英語にすると？","options":["The teacher as well as the students were tired.","The teacher as well as the students is tired.","The teacher as well as the students was tired.","The teacher as good as the students was tired."],"answer":2,"back":"答え：The teacher as well as the students was tired.\nコツ：as well as の前（the teacher＝1人）に合わせる → was\n（本冊435）"},{"id":"c42","category":"is・are などの形を合わせる","front":"「そのケーキのほとんどが食べられた。」\nMost of で始めて英語にすると？","options":["Most of the cake were eaten.","Most the cake was eaten.","Most of the cake was eat.","Most of the cake was eaten."],"answer":3,"back":"答え：Most of the cake was eaten.\nコツ：of の後ろ（the cake＝1つ）に合わせる → was。the students なら were\n（本冊436〜438）"},{"id":"c43","category":"is・are などの形を合わせる","front":"「箱の中にりんごが3つある。」\n英語にすると？","options":["There is three apples in the box.","There are three apple in the box.","There are three apples in the box.","Three apples there are in the box."],"answer":2,"back":"答え：There are three apples in the box.\nコツ：There のあとは後ろの物に合わせる。3つなら are\n（本冊439〜440）"},{"id":"c44","category":"is・are などの形を合わせる","front":"「この町の子どもの数は減っている。」\n英語にすると？","options":["The number of children in this town is decreasing.","The number of children in this town are decreasing.","A number of children in this town is decreasing.","The number of child in this town is decreasing."],"answer":0,"back":"答え：The number of children in this town is decreasing.\nコツ：the number of 〜「〜の数」は1つの数なので is\n（本冊441〜442）"},{"id":"c45","category":"is・are などの形を合わせる","front":"「10キロは歩くには遠すぎる。」\n英語にすると？","options":["Ten kilometers is too far to walk.","Ten kilometers are too far to walk.","Ten kilometer is too far to walk.","Ten kilometers is too far to walking."],"answer":0,"back":"答え：Ten kilometers is too far to walk.\nコツ：きょり・お金・時間は1つのまとまりなので is\n（本冊443〜444）"},{"id":"c46","category":"is・are などの形を合わせる","front":"「お金持ちがいつも幸せとはかぎらない。」\nthe rich を使って英語にすると？","options":["The rich is not always happy.","The rich are not always happy.","Rich are not always happy.","The riches are not always happy."],"answer":1,"back":"答え：The rich are not always happy.\nコツ：the rich ＝「お金持ちの人たち」なので are\n（本冊445）"},{"id":"c47","category":"is・are などの形を合わせる","front":"「私には東京に住んでいる友だちが2人いる。」\nwho を使って英語にすると？","options":["I have two friends who lives in Tokyo.","I have two friend who live in Tokyo.","I have two friends who live in Tokyo.","I have two friends who they live in Tokyo."],"answer":2,"back":"答え：I have two friends who live in Tokyo.\nコツ：who のあとは前の two friends に合わせる → live（lives にしない）\n（本冊446）"},{"id":"c48","category":"is・are などの形を合わせる","front":"「その店のケーキの値段は高い。」\n英語にすると？","options":["The price of the cakes at the shop are high.","The price of the cakes at the shop is high.","The prices of the cakes at the shop is high.","The cakes of the price at the shop is high."],"answer":1,"back":"答え：The price of the cakes at the shop is high.\nコツ：中心は price（値段＝1つ）。近くの cakes につられて are にしない\n（本冊447）"},{"id":"c49","category":"聞き方（How＋〜）","front":"「どのくらいよく映画を見に行きますか。」\n英語にすると？","options":["How far do you go to the movies?","How often do you go to the movies?","How long do you go to the movies?","How often you go to the movies?"],"answer":1,"back":"答え：How often do you go to the movies?\nコツ：「何回くらい」は How often。きょりは How far、長さは How long\n（本冊450〜453）"},{"id":"c50","category":"聞き方（How＋〜）","front":"「駅まで歩いてどれくらい時間がかかりますか。」\n英語にすると？","options":["How long does it takes to walk to the station?","How far does it take to walk to the station?","How long does it take to walk to the station?","How long it takes to walk to the station?"],"answer":2,"back":"答え：How long does it take to walk to the station?\nコツ：「時間がかかる」は How long does it take (to 〜)?\n（本冊452）"},{"id":"c51","category":"聞き方（How＋〜）","front":"「この教室には生徒が何人いますか。」\n英語にすると？","options":["How much students are there in this classroom?","How many student are there in this classroom?","How many students are there in this classroom?","How many students there are in this classroom?"],"answer":2,"back":"答え：How many students are there in this classroom?\nコツ：数えられる物は How many ＋ ＿s。お金や量は How much\n（本冊449）"},{"id":"c52","category":"文の中の「どこ・なに」","front":"「彼女がどこに住んでいるのか知りたい。」\n英語にすると？","options":["I want to know where she lives.","I want to know where does she live.","I want to know where she live.","I want to know where lives she."],"answer":0,"back":"答え：I want to know where she lives.\nコツ：文の中では where she lives の順。does は入れない\n（本冊454〜455）"},{"id":"c53","category":"「〜と思う？」の聞き方","front":"「彼はどこにいると思いますか。」\n英語にすると？","options":["Do you think where he is?","Where do you think he is?","Where do you think is he?","Where are you think he is?"],"answer":1,"back":"答え：Where do you think he is?\nコツ：Where を先頭に出して do you think を入れる。後ろは he is の順\n（本冊456〜457）"},{"id":"c54","category":"「〜しないの？」への答え","front":"「Don't you like coffee? ─ うん、好きじゃないよ。」\n「うん、好きじゃない」を英語にすると？","options":["No, I don't.","Yes, I don't.","Yes, I do.","No, I do."],"answer":0,"back":"答え：No, I don't.\nコツ：好きじゃないなら No。日本語の「うん」につられて Yes にしない\n（本冊458）"},{"id":"c55","category":"「〜だよね？」","front":"「今日は寒いよね？」\n英語にすると？","options":["It is cold today, is it?","It is cold today, isn't it?","It is cold today, doesn't it?","It is cold today, isn't today?"],"answer":1,"back":"答え：It is cold today, isn't it?\nコツ：not なしの文には isn't it?。is の文なので doesn't にしない\n（本冊459〜460）"},{"id":"c56","category":"「〜だよね？」","front":"「お昼を食べに行こうよ、ね？」\nLet's で始めて英語にすると？","options":["Let's go for lunch, shall we?","Let's go for lunch, will you?","Let's go for lunch, don't we?","Let's go for lunch, shall us?"],"answer":0,"back":"答え：Let's go for lunch, shall we?\nコツ：Let's 〜 のあとの「ね？」は shall we?\n（本冊461〜462）"},{"id":"c57","category":"決まった聞き方","front":"「どこの出身ですか。」\ncome を使って英語にすると？","options":["Where did you come from?","Where are you come from?","Where do you come from?","Where you come from?"],"answer":2,"back":"答え：Where do you come from?\nコツ：出身はずっと変わらないので do you come。did you come にしない\n（本冊463）"},{"id":"c58","category":"決まった聞き方","front":"What is your new teacher like?\nどういう意味？","options":["新しい先生は何が好きですか。","新しい先生はどんな人ですか。","新しい先生はだれが好きですか。","新しい先生に似ているのはだれですか。"],"answer":1,"back":"答え：新しい先生はどんな人ですか。\nコツ：What is ＿ like? は「＿はどんな感じ？」。like は「好き」ではない\n（本冊464〜465）"},{"id":"c59","category":"決まった聞き方","front":"「この映画をどう思いますか。」\n英語にすると？","options":["How do you think of this movie?","What do you think of this movie?","What do you think this movie?","What are you think of this movie?"],"answer":1,"back":"答え：What do you think of this movie?\nコツ：「どう思う」は What do you think of 〜?。「どう」につられて How にしない\n（本冊466）"},{"id":"c60","category":"決まった聞き方","front":"What has become of the old school?\nどういう意味？","options":["あの古い学校は何になりたいのですか。","何があの古い学校になったのですか。","あの古い学校で何をしたのですか。","あの古い学校はどうなったのですか。"],"answer":3,"back":"答え：あの古い学校はどうなったのですか。\nコツ：What has become of ＿? は「＿はどうなった？」\n（本冊467）"},{"id":"c61","category":"決まった聞き方","front":"「どうして昨日来なかったの？」\nHow come で始めて英語にすると？","options":["How come you didn't come yesterday?","How come did you not come yesterday?","How come didn't you come yesterday?","How come you don't came yesterday?"],"answer":0,"back":"答え：How come you didn't come yesterday?\nコツ：How come のあとはふつうの文の順（you didn't …）\n（本冊468）"},{"id":"c62","category":"決まった聞き方","front":"What did you go to Tokyo for?\nどういう意味？","options":["どうやって東京へ行ったのですか。","だれといっしょに東京へ行ったのですか。","何のために東京へ行ったのですか。","東京で何を買ったのですか。"],"answer":2,"back":"答え：何のために東京へ行ったのですか。\nコツ：What 〜 for? は「何のために〜？」\n（本冊469）"},{"id":"c63","category":"決まった聞き方","front":"Why don't we go swimming?\nどういう意味？","options":["（あなたが）泳ぎに行ったらどう？","私たちは泳ぎに行きたくない。","どうして泳ぎに行ったの？","いっしょに泳ぎに行こうよ。"],"answer":3,"back":"答え：いっしょに泳ぎに行こうよ。\nコツ：Why don't we 〜? は「いっしょに〜しよう」。Why don't you 〜? は「〜したらどう？」\n（本冊470〜471）"},{"id":"c64","category":"決まった聞き方","front":"「散歩に行くのはどう？」\nWhat about を使って英語にすると？","options":["What about go for a walk?","What about going for a walk?","What about to go for a walk?","What about went for a walk?"],"answer":1,"back":"答え：What about going for a walk?\nコツ：What about のあとは ＿ing（going）\n（本冊472）"},{"id":"c65","category":"聞くふりの言い方","front":"Who knows?\nどういう意味？","options":["だれでも知っているよ。","だれかが知っているよ。","あなたは知っているの？","だれにもわからないよ。"],"answer":3,"back":"答え：だれにもわからないよ。\nコツ：「だれが知ってる？」→「だれも知らない」という意味\n（本冊473）"},{"id":"c66","category":"聞くふりの言い方","front":"「今さら泣いてもむだだ。」\nIt is no use を使って英語にすると？","options":["It is no use crying now.","It is no use cry now.","It is not use crying now.","It is no used crying now."],"answer":0,"back":"答え：It is no use crying now.\nコツ：「〜してもむだ」は It is no use ＿ing\n（本冊474）"},{"id":"c67","category":"What と Where の使い分け","front":"「日本の首都はどこですか。」\n英語にすると？","options":["Where is the capital of Japan?","What the capital of Japan is?","What is the capital of Japan?","Where the capital of Japan is?"],"answer":2,"back":"答え：What is the capital of Japan?\nコツ：答えが「東京」という名前なら What。場所を聞くなら Where\n（本冊448）"}]},{"id":"ronpyo-374","group":"論理・表現 第11〜13章（12月期末）","title":"論表 比較の前半（本冊374〜402と同じ文法）","subject":"論理・表現","order":1.5,"version":3,"cards":[{"id":"k374","category":"as ～ as（同じくらい）","front":"「エミはお姉さんと同じくらい速く泳ぐ。」\nEmi swims as ＿＿＿ as her older sister.","options":["faster","fast","fastest","more fast"],"answer":1,"back":"答え：fast\nEmi swims as fast as her older sister.\nコツ：as と as ではさまれたら、もとの形（fast）のまま。-er はつけない。\n（本冊374）"},{"id":"k375","category":"as ～ as（同じくらい）","front":"「この川は今も20年前と同じくらいきれいだ。」\nThis river is as clean today as it ＿＿＿ twenty years ago.","options":["is","does","was","has been"],"answer":2,"back":"答え：was\nThis river is as clean today as it was twenty years ago.\nコツ：twenty years ago（20年前）は昔のこと。昔なので was。\n（本冊375）"},{"id":"k376","category":"as ～ as（同じくらい）","front":"「そのゲームはみんなが言うほどおもしろくなかった。」\nThe game was ＿＿＿ said.\n正しい順番はどれ？","back":"答え：not so exciting as people\nThe game was not so exciting as people said.\nコツ：「～ほど…ない」は not so … as ～。not so → exciting → as → people の順。\n（本冊376）","options":["not so exciting as people","so not exciting as people","not exciting so as people","not so as exciting people"],"answer":0},{"id":"k377","category":"as ～ as（同じくらい）","front":"「私は兄と同じくらいたくさんのマンガを読んだ。」\nI have read as ＿＿＿ comics as my brother.","options":["much","many","more","lot of"],"answer":1,"back":"答え：many\nI have read as many comics as my brother.\nコツ：comics は1冊、2冊と数えられる物 → many。数えられない物（お金・水・時間）なら much。\n（本冊377）"},{"id":"k378","category":"～倍・～分の1","front":"「私の犬はあなたの犬の2倍重い。」\nMy dog is ＿＿＿ as heavy as yours.","options":["two","double times","twice","twice times"],"answer":2,"back":"答え：twice\nMy dog is twice as heavy as yours.\nコツ：「2倍」は twice の1語だけ。as heavy as の前に置く。\n（本冊378）"},{"id":"k379","category":"～倍・～分の1","front":"「この塔はあのビルの3倍高い。」\nThis tower is ＿＿＿ as tall as that building.","options":["three time","three times","the third times","times three"],"answer":1,"back":"答え：three times\nThis tower is three times as tall as that building.\nコツ：「3倍」は three times（times に s がつく）。as tall as の前に置く。\n（本冊379）"},{"id":"k380","category":"～倍・～分の1","front":"「この池はあの池の3分の1の広さだ。」\nThis pond is ＿＿＿ that one.\n正しい順番はどれ？","back":"答え：one third as large as\nThis pond is one third as large as that one.\nコツ：「3分の1」one third を先に。そのあと as large as。\n（本冊380）","options":["as large as one third","third one as large as","one third as large as","one as third large as"],"answer":2},{"id":"k381","category":"～倍・～分の1","front":"「この新しい車は、古い車の半分のガソリンしか使わない。」\nThis new car uses half as ＿＿＿ gas as the old one.","options":["many","much","more","most"],"answer":1,"back":"答え：much\nThis new car uses half as much gas as the old one.\nコツ：gas（ガソリン）は水と同じで数えられない物 → much。\n（本冊381）"},{"id":"k382","category":"～倍・～分の1","front":"「新しい図書館は古い図書館の2倍の大きさだ。」\nThe new library is twice ＿＿＿ of the old one.","options":["as size","size as","the size","the large"],"answer":2,"back":"答え：the size\nThe new library is twice the size of the old one.\nコツ：後ろに of があるので「the size of（～の大きさ）」。twice the size of ＝ twice as large as。\n（本冊382）"},{"id":"k383","category":"～倍・～分の1","front":"「このボートはあの車の10分の1の速さで進む。」\nThis boat moves at ＿＿＿ that car.\n正しい順番はどれ？","back":"答え：one-tenth the speed of\nThis boat moves at one-tenth the speed of that car.\nコツ：「10分の1」→「速さ（the speed）」→「～の（of）」。日本語と同じ順番。\n（本冊383）","options":["the speed of one-tenth","one-tenth the speed of","speed the one-tenth of","of the one-tenth speed"],"answer":1},{"id":"k384","category":"as ～ as のきまった言い方","front":"「友だちとできるだけ多くの時間を過ごしなさい。」\nSpend ＿＿＿ with your friends.","options":["as time much as possible","as much time as possible","time as much as possible","as much as possible time"],"answer":1,"back":"答え：as much time as possible\nSpend as much time as possible with your friends.\nコツ：「できるだけ」は as ～ as possible。much time はくっつけたまま、as と as ではさむ。\n（本冊384）"},{"id":"k385","category":"as ～ as のきまった言い方","front":"「できるだけ大きな声で話しなさい。」\nSpeak as loudly as you ＿＿＿.","options":["possible","can","are","able"],"answer":1,"back":"答え：can\nSpeak as loudly as you can.\nコツ：as ～ as you can ＝「あなたにできるかぎり」＝ できるだけ。you があるので possible ではなく can。\n（本冊385）"},{"id":"k386","category":"as ～ as のきまった言い方","front":"上と下が同じ意味になるように、＿＿＿ に入る言葉は？\n上：She is a singer rather than an actor.\n下：She is not so much an ＿①＿ as a ＿②＿.","back":"答え：① actor ② singer\nShe is not so much an actor as a singer.\nコツ：上の rather than の後ろの actor が前。本当の方の singer が最後。\n（本冊386）","options":["① singer ② actor","① actor ② actor","① singer ② singer","① actor ② singer"],"answer":3},{"id":"k387","category":"as ～ as のきまった言い方","front":"「彼は私にあいさつさえしなかった。」\nHe did not so much as ＿＿＿ hello to me.","options":["saying","said","say","to say"],"answer":2,"back":"答え：say\nHe did not so much as say hello to me.\nコツ：did not のあとは、もとの形（say）。so much as がはさまっても同じ。\n（本冊387）"},{"id":"k388","category":"as ～ as のきまった言い方","front":"「彼女はさようならも言わずに帰った。」\nShe left without so much as ＿＿＿ goodbye.","options":["say","saying","said","to say"],"answer":1,"back":"答え：saying\nShe left without so much as saying goodbye.\nコツ：without（～しないで）のあとは -ing の形。\n（本冊388）"},{"id":"k389","category":"as ～ as のきまった言い方","front":"「彼は今までいた中でも、だれにも負けないすごい野球選手だった。」\nHe was as great ＿＿＿ as ever lived.","options":["baseball player","the baseball player","a baseball player","baseball players"],"answer":2,"back":"答え：a baseball player\nHe was as great a baseball player as ever lived.\nコツ：as great のすぐ後ろは「a ＋ 1人」。as great a baseball player の順番。\n（本冊389）"},{"id":"k390","category":"as ～ as のきまった言い方","front":"「これは私が今まで見たどの映画にも負けないくらいおもしろい。」\nThis is as exciting a movie as ＿＿＿ I have ever seen.","options":["all","every","any","some"],"answer":2,"back":"答え：any\nThis is as exciting a movie as any I have ever seen.\nコツ：「どの～にも負けない」は as ～ as any。any ＝「どれでも」。\n（本冊390）"},{"id":"k391","category":"「～も」「たった～」","front":"「その試合には1万人もの人が来た。」\n＿＿＿ 10,000 people came to the game.","options":["As much as","As many as","As few as","As little as"],"answer":1,"back":"答え：As many as\nAs many as 10,000 people came to the game.\nコツ：人は数えられる → many。「～人も（多い！）」と言うので as many as。\n（本冊391）"},{"id":"k392","category":"「～も」「たった～」","front":"「そのペンはたった100円で買える。」\nYou can buy the pen for as ＿＿＿ as 100 yen.","options":["few","small","little","less"],"answer":2,"back":"答え：little\nYou can buy the pen for as little as 100 yen.\nコツ：お金は数えられない物のなかま → little。「たった～」と少なさを言うときは as little as。\n（本冊392）"},{"id":"k393","category":"「～も」「たった～」","front":"「父は早くも朝4時には起きた。」\nMy father got up as ＿＿＿ as four in the morning.","options":["soon","early","fast","quickly"],"answer":1,"back":"答え：early\nMy father got up as early as four in the morning.\nコツ：時刻が「早い」は early（fast は動きが速いこと）。as early as 4 ＝ 早くも4時に。\n（本冊393）"},{"id":"k394","category":"-er の形のいろいろ","front":"「この川はあの川よりずっと長い。」\nThis river is ＿＿＿ longer than that one.","options":["very","much","more","so"],"answer":1,"back":"答え：much\nThis river is much longer than that one.\nコツ：longer のような -er の形を「ずっと」と強めるのは much。very は使えない。\n（本冊394）"},{"id":"k395","category":"-er の形のいろいろ","front":"上と下が同じ意味になるように、＿＿＿ に入る言葉は？\n上：Science is not as hard as math for me.\n下：Science is ＿①＿ ＿②＿ than math for me.","back":"答え：① less ② hard\nScience is less hard than math for me.\nコツ：not as hard as（ほど難しくない）＝ less hard than。less は more の反対。\n（本冊395）","options":["① less ② hard","① more ② hard","① less ② harder","① more ② harder"],"answer":0},{"id":"k396","category":"-er の形のいろいろ","front":"「アヤはかしこいというより、むしろやさしい。」\nAya is more ＿＿＿ than clever.","options":["kinder","kind","kindest","the kinder"],"answer":1,"back":"答え：kind\nAya is more kind than clever.\nコツ：1人の2つの性格をくらべるときは more ＋ もとの形（kind）。kinder than にはしない。\n（本冊396）"},{"id":"k397","category":"-er の形のいろいろ","front":"「このスイカはあのメロンの3倍重い。」\nThis watermelon is ＿＿＿ that melon.\n正しい順番はどれ？","back":"答え：three times heavier than\nThis watermelon is three times heavier than that melon.\nコツ：「3倍」three times を先に。そのあと heavier than（より重い）。\n（本冊397）","options":["heavier three times than","times three heavier than","three heavier times than","three times heavier than"],"answer":3},{"id":"k398","category":"the ＋ -er の形","front":"「ユウタは2人の兄弟のうちで背が高いほうだ。」\nYuta is ＿＿＿ of the two brothers.","options":["taller","the tallest","the taller","tallest"],"answer":2,"back":"答え：the taller\nYuta is the taller of the two brothers.\nコツ：of the two（2人のうちで）があるときは the ＋ -er の形。2人だけなので -est は使わない。\n（本冊398）"},{"id":"k399","category":"the ＋ -er の形","front":"「歌えば歌うほど、うまくなる。」\nThe more you sing, ＿＿＿ you will become.","options":["better","the better","the best","best"],"answer":1,"back":"答え：the better\nThe more you sing, the better you will become.\nコツ：「～すればするほど…」。前に The があれば、後ろにも the をつける。\n（本冊399）"},{"id":"k400","category":"the ＋ -er の形","front":"「練習に時間をかければかけるほど、上手になる。」\n＿＿＿ spend practicing, the better you will play.\n正しい順番はどれ？","back":"答え：The more time you\nThe more time you spend practicing, the better you will play.\nコツ：more time はくっつけたまま前に出す。The more time → you の順。\n（本冊400）","options":["The more you time","More the time you","The more time you","The time more you"],"answer":2},{"id":"k401","category":"the ＋ -er の形","front":"「正直なので、私はなおさら彼女が好きだ。」\nI like her all the ＿＿＿ for her honesty.","options":["best","more good","better","well"],"answer":2,"back":"答え：better\nI like her all the better for her honesty.\nコツ：all the better for ～ ＝「～なので、なおさら」。good を -er の形にすると better。\n（本冊401）"},{"id":"k402","category":"the ＋ -er の形","front":"「彼女はお金持ちなのに、少しも幸せではない。」\nShe is ＿＿＿ the happier for her wealth.","options":["no","none","not","never"],"answer":1,"back":"答え：none\nShe is none the happier for her wealth.\nコツ：none the -er の形 for ～ ＝「～なのに、少しも…ない」。the の前は none と決まっている。\n（本冊402）"}]},{"id":"ronpyo-403","group":"論理・表現 第11〜13章（12月期末）","title":"論表 比較の後半（本冊403〜430と同じ文法）","subject":"論理・表現","order":1.6,"version":1,"cards":[{"id":"k403","category":"〜より多い・少ない","front":"「私はもう1か月以上ピアノを練習している。」\nI have practiced the piano for ＿＿＿.","options":["a month more than","than more a month","more than a month","more a month than"],"answer":2,"back":"答え：more than a month\nI have practiced the piano for more than a month.\nコツ：「〜より多く」は more than を先に言って、そのあとに a month。\n（本冊403）"},{"id":"k404","category":"〜より多い・少ない","front":"「この宿題は2時間もかからずに終わる。」\nThis homework takes ＿＿＿.","options":["two hours less than","less than two hours","less two hours than","than less two hours"],"answer":1,"back":"答え：less than two hours\nThis homework takes less than two hours.\nコツ：less than ＝「〜より少ない」。less than を先に、そのあと two hours。\n（本冊404）"},{"id":"k405","category":"たった〜・〜も","front":"「財布にはたった500円しかない。」\nI have ＿＿＿ 500 yen in my wallet.","options":["no less than","as much as","at least","no more than"],"answer":3,"back":"答え：no more than\nI have no more than 500 yen in my wallet.\nコツ：no more than ＝ only（たった〜しか）。「少ない！」の気持ち。\n（本冊405）"},{"id":"k406","category":"たった〜・〜も","front":"「その自転車は5万円もした。」\nThe bike cost ＿＿＿ 50,000 yen.","options":["no less than","no more than","not more than","less than"],"answer":0,"back":"答え：no less than\nThe bike cost no less than 50,000 yen.\nコツ：no less than ＝ as much as（〜も）。「多い！」の気持ち。no more than（たった）と反対。\n（本冊406）"},{"id":"k407","category":"〜でないのと同じ・〜に負けない","front":"「コウモリは鳥ではない。ネコが鳥でないのと同じだ。」\nA bat is ＿＿＿ a bird than a cat is.","options":["no less","no more","any more","not more"],"answer":1,"back":"答え：no more\nA bat is no more a bird than a cat is.\nコツ：no more 〜 than … ＝「…と同じで〜ではない」。どっちも「ちがう！」と言いたいときは no more。\n（本冊407）"},{"id":"k408","category":"〜でないのと同じ・〜に負けない","front":"「私がニンジンを好きでないのと同じで、兄も好きではない。」\nMy brother does not like carrots ＿＿＿ I do.","options":["no more than","any more as","any more than","no longer than"],"answer":2,"back":"答え：any more than\nMy brother does not like carrots any more than I do.\nコツ：前に not があるので any more than。not 〜 any more than ＝ no more 〜 than。\n（本冊408）"},{"id":"k409","category":"〜でないのと同じ・〜に負けない","front":"「このパンは、あの有名な店のパンに負けないくらいおいしい。」\nThis bread is ＿＿＿ the bread at that famous shop.","options":["delicious no less than","less no delicious than","no delicious less than","no less delicious than"],"answer":3,"back":"答え：no less delicious than\nThis bread is no less delicious than the bread at that famous shop.\nコツ：「負けないくらい〜」は no less 〜 than。no less → delicious → than の順。\n（本冊409）"},{"id":"k410","category":"-er の形のきまった言い方","front":"「ドアを開けたのは、なんとあの有名な歌手だった。」\nThe person who opened the door was ＿＿＿ the famous singer.","options":["none other than","none another than","not other than","nobody more than"],"answer":0,"back":"答え：none other than\nThe person who opened the door was none other than the famous singer.\nコツ：「なんと〜その人」は none other than。none と other の組み合わせで決まっている。\n（本冊410）"},{"id":"k411","category":"-er の形のきまった言い方","front":"「兄はテストの前の夜にゲームをするほどばかではない。」\nMy brother ＿＿＿ play games the night before a test.","options":["knows than better to","knows better than to","better knows than to","knows better to than"],"answer":1,"back":"答え：knows better than to\nMy brother knows better than to play games the night before a test.\nコツ：knows better than to 〜 ＝「〜するほどばかではない」。knows → better → than → to の順。\n（本冊411）"},{"id":"k412","category":"-er の形のきまった言い方","front":"「私は自転車にも乗れない。まして車の運転なんてむりだ。」\nI can't ride a bike, ＿＿＿.","options":["less much drive a car","drive a car much less","much less drive a car","much drive less a car"],"answer":2,"back":"答え：much less drive a car\nI can't ride a bike, much less drive a car.\nコツ：前に can't（できない）があって「まして〜なんて」は much less。much less を先に言う。\n（本冊412）"},{"id":"k413","category":"-er の形のきまった言い方","front":"「まちがっている言葉はどれ？」\nMy grandma ①doesn't ②drive ③no longer, so I ④take her home.","options":["doesn't","drive","no longer","take"],"answer":2,"back":"答え：③ no longer → any longer\nMy grandma doesn't drive any longer, so I take her home.\nコツ：doesn't に not が入っているので any longer。no longer なら doesn't を使わず no longer drives。\n（本冊413）"},{"id":"k414","category":"〜より上・下（to を使う）","front":"「このカメラは古いカメラよりすぐれている。」\nThis camera is superior ＿＿＿ the old one.","options":["than","for","from","to"],"answer":3,"back":"答え：to\nThis camera is superior to the old one.\nコツ：superior（すぐれている）は than ではなく to を使う。\n（本冊414）"},{"id":"k415","category":"〜より上・下（to を使う）","front":"「私はバスに乗るより歩くほうが好きだ。」\nI prefer walking ＿＿＿ taking the bus.","options":["to","than","from","for"],"answer":0,"back":"答え：to\nI prefer walking to taking the bus.\nコツ：prefer 〜 to … ＝「…より〜が好き」。prefer のときは than ではなく to。\n（本冊415）"},{"id":"k416","category":"〜より上・下（to を使う）","front":"「ケンは私より3歳年上だ。」\nKen is three years ＿＿＿ me.","options":["older to","senior to","elder than","senior than"],"answer":1,"back":"答え：senior to\nKen is three years senior to me.\nコツ：senior（年上）は to を使う。older なら than（older than I）。\n（本冊416）"},{"id":"k417","category":"いちばん〜","front":"「タケシは5人の男の子の中でいちばん背が高い。」\nTakeshi is the tallest ＿＿＿ the five boys.","options":["in","than","of","at"],"answer":2,"back":"答え：of\nTakeshi is the tallest of the five boys.\nコツ：the five boys のように「なかまの数」が来たら of。「場所」なら in。\n（本冊417）"},{"id":"k418","category":"いちばん〜","front":"「まちがっている言葉はどれ？」\nThis ramen shop is ①too far ②the best ③in our ④town.","options":["too","the","in","town"],"answer":0,"back":"答え：① too → by\nThis ramen shop is by far the best in our town.\nコツ：「ダントツでいちばん」は by far the -est の形。too far は「遠すぎる」になってしまう。\n（本冊418）"},{"id":"k419","category":"いちばん〜","front":"「これは私が今まで見た中で、まさにいちばんの映画だ。」\nThis is ＿＿＿ movie I have ever seen.","options":["very the best","the best very","best the very","the very best"],"answer":3,"back":"答え：the very best\nThis is the very best movie I have ever seen.\nコツ：「まさにいちばん」は the very best。the → very → best の順。\n（本冊419）"},{"id":"k420","category":"いちばん〜","front":"「このビルは私たちの町で2番目に高い。」\nThis building is the ＿＿＿ in our city.","options":["second taller","second tallest","tallest second","two tallest"],"answer":1,"back":"答え：second tallest\nThis building is the second tallest in our city.\nコツ：「2番目に〜」は the second ＋ -est の形。second を先に言う。\n（本冊420）"},{"id":"k421","category":"いちばん〜","front":"「まちがっている言葉はどれ？」\nKyoto is ①one of the ②most ③beautiful ④city in Japan.","options":["one","most","beautiful","city"],"answer":3,"back":"答え：④ city → cities\nKyoto is one of the most beautiful cities in Japan.\nコツ：one of the 〜（〜のうちの1つ）は、たくさんの中から選ぶので cities と -s がつく。\n（本冊421）"},{"id":"k422","category":"いちばん〜","front":"「これは今まで食べた中でいちばんおいしいカレーだ。」\nThis is the ＿＿＿ curry I've ever had.","options":["best","better","good","most good"],"answer":0,"back":"答え：best\nThis is the best curry I've ever had.\nコツ：the と I've ever（今までに）があれば「いちばん」。good の -est の形は best。\n（本冊422）"},{"id":"k423","category":"いちばん〜","front":"「こんなに大きな犬は見たことがない。」\nThis is the biggest dog ＿＿＿.","options":["I have never seen","ever I have seen","I have ever seen","have I ever seen"],"answer":2,"back":"答え：I have ever seen\nThis is the biggest dog I have ever seen.\nコツ：「見たことがない」でも英語は never ではなく ever。「今まで見た中でいちばん大きい」と考える。\n（本冊423）"},{"id":"k424","category":"いちばん〜","front":"「少なくとも1日に8時間は寝なさい。」\nSleep ＿＿＿ eight hours a day.","options":["at most","at least","at last","at less"],"answer":1,"back":"答え：at least\nSleep at least eight hours a day.\nコツ：「少なくとも」は at least。「多くても」は at most。\n（本冊424）"},{"id":"k425","category":"ほかのどれより〜","front":"「このクラスでミホほど速く走る生徒はいない。」\nNo ＿＿＿ runs as fast as Miho.","options":["other students in this class","in this class other student","other in this class student","other student in this class"],"answer":3,"back":"答え：other student in this class\nNo other student in this class runs as fast as Miho.\nコツ：No other のあとは student（-s がつかない1つの形）。runs もヒント。in this class はそのあと。\n（本冊425）"},{"id":"k426","category":"ほかのどれより〜","front":"「健康ほど大切なものはない。」\n＿＿＿ is as important as health.","options":["Nothing","Anything","Something","Everything"],"answer":0,"back":"答え：Nothing\nNothing is as important as health.\nコツ：「〜ほど大切なものはない」は Nothing is as 〜 as …。\n（本冊426）"},{"id":"k427","category":"ほかのどれより〜","front":"「日本で富士山より高い山はない。」\nNo other ＿＿＿ is higher than Mt. Fuji.","options":["in Japan mountain","mountains in Japan","mountain in Japan","Japan mountain in"],"answer":2,"back":"答え：mountain in Japan\nNo other mountain in Japan is higher than Mt. Fuji.\nコツ：No other のあとは mountain（-s がつかない1つの形）。is もヒント。in Japan はそのあと。\n（本冊427）"},{"id":"k428","category":"ほかのどれより〜","front":"「家族より大切なものはない。」\n＿＿＿ important than my family.","options":["Nothing is most","Nothing is more","Anything is more","Nothing more is"],"answer":1,"back":"答え：Nothing is more\nNothing is more important than my family.\nコツ：than があるので more。「〜より大切なものはない」は Nothing is more 〜 than …。\n（本冊428）"},{"id":"k429","category":"ほかのどれより〜","front":"「ダチョウはほかのどの鳥よりも大きい。」\nAn ostrich is bigger than ＿＿＿.","options":["any other birds","all other bird","other any bird","any other bird"],"answer":3,"back":"答え：any other bird\nAn ostrich is bigger than any other bird.\nコツ：any other のあとは bird（-s がつかない1つの形）。「どの1羽とくらべても」と考える。\n（本冊429）"},{"id":"k430","category":"ほかのどれより〜","front":"「私はほかの何よりもサッカーが好きだ。」\nI like soccer more than ＿＿＿.","options":["anything else","nothing else","else anything","anything other"],"answer":0,"back":"答え：anything else\nI like soccer more than anything else.\nコツ：「ほかの何よりも」は than anything else。anything → else の順。\n（本冊430）"}]},{"id":"ronpyo-431","group":"論理・表現 第11〜13章（12月期末）","title":"論表 is か are か（本冊431〜447と同じ文法）","subject":"論理・表現","order":1.7,"version":1,"cards":[{"id":"k431a","category":"is か are か（and・or）","front":"「ケンとユミは2人とも、明日テニスをする予定だ。」\nBoth Ken and Yumi ＿＿＿ going to play tennis tomorrow.","options":["is","are","am","be"],"answer":1,"back":"答え：are\nBoth Ken and Yumi are going to play tennis tomorrow.\nコツ：both ～ and …（～も…も両方）は2人の話なので are。\n（本冊431）"},{"id":"k431b","category":"is か are か（and・or）","front":"「姉も兄も、もう昼ごはんを食べた。」\nBoth my sister and my brother ＿＿＿ already eaten lunch.","options":["has","is","was","have"],"answer":3,"back":"答え：have\nBoth my sister and my brother have already eaten lunch.\nコツ：both ～ and … は2人の話なので、has ではなく have。\n（本冊431）"},{"id":"k432a","category":"is か are か（and・or）","front":"「友だちだけでなく、先生もそのニュースを聞いた。」\nNot only my friends but also my teacher ＿＿＿ heard the news.","options":["has","have","are","is"],"answer":0,"back":"答え：has\nNot only my friends but also my teacher has heard the news.\nコツ：but also のすぐ後ろの my teacher（1人）に合わせて has。friends につられない。\n（本冊432）"},{"id":"k432b","category":"is か are か（and・or）","front":"「トムだけでなく、トムのお兄さんたちも野球が上手だ。」\nNot only Tom but also his brothers ＿＿＿ good at baseball.","options":["is","am","are","has"],"answer":2,"back":"答え：are\nNot only Tom but also his brothers are good at baseball.\nコツ：but also のすぐ後ろの his brothers（2人以上）に合わせて are。\n（本冊432）"},{"id":"k433a","category":"is か are か（and・or）","front":"「ケンも、ケンの友だちも、パーティーに来ない。」\nNeither Ken nor his friends ＿＿＿ coming to the party.","options":["is","am","be","are"],"answer":3,"back":"答え：are\nNeither Ken nor his friends are coming to the party.\nコツ：nor のすぐ後ろの his friends（2人以上）に合わせて are。\n（本冊433）"},{"id":"k433b","category":"is か are か（and・or）","front":"「両親も兄も、今は家にいない。」\nNeither my parents nor my brother ＿＿＿ at home now.","options":["is","are","am","be"],"answer":0,"back":"答え：is\nNeither my parents nor my brother is at home now.\nコツ：nor のすぐ後ろの my brother（1人）に合わせて is。parents につられない。\n（本冊433）"},{"id":"k434a","category":"is か are か（and・or）","front":"「彼女か私のどちらかが、部屋をそうじする予定だ。」\nEither she or I ＿＿＿ going to clean the room.","options":["is","are","am","be"],"answer":2,"back":"答え：am\nEither she or I am going to clean the room.\nコツ：or のすぐ後ろの I に合わせて am。\n（本冊434）"},{"id":"k434b","category":"is か are か（and・or）","front":"「トムか私のどちらかが、皿を洗わないといけない。」\nEither Tom or I ＿＿＿ to wash the dishes.","options":["has","have","is","having"],"answer":1,"back":"答え：have\nEither Tom or I have to wash the dishes.\nコツ：or のすぐ後ろの I に合わせて have（I has とは言わない）。\n（本冊434）"},{"id":"k435a","category":"is か are か（and・or）","front":"「あなただけでなく、先生も怒っていた。」\nThe teacher as well as you ＿＿＿ angry.","options":["were","are","have","was"],"answer":3,"back":"答え：was\nThe teacher as well as you was angry.\nコツ：as well as は前に合わせる。The teacher（1人）なので was。you につられない。\n（本冊435）"},{"id":"k435b","category":"is か are か（and・or）","front":"まちがっている言葉はどれ？\nMy brother as well as my ①parents ②are ③coming ④to dinner tonight.","options":["parents","are","coming","to"],"answer":1,"back":"答え：② are → is\nMy brother as well as my parents is coming to dinner tonight.\nコツ：as well as の前の My brother（1人）に合わせて is。\n（本冊435）"},{"id":"k436a","category":"is か are か（～のほとんど・～分の1）","front":"「このクラスの生徒のほとんどは、学校の近くに住んでいる。」\nMost of the students in this class ＿＿＿ near the school.","options":["live","lives","living","to live"],"answer":0,"back":"答え：live\nMost of the students in this class live near the school.\nコツ：most of の後ろの students（2人以上）に合わせて、s なしの live。\n（本冊436）"},{"id":"k436b","category":"is か are か（～のほとんど・～分の1）","front":"「この部屋の家具のほとんどは古い。」\nMost of the furniture in this room ＿＿＿ old.","options":["are","were","is","be"],"answer":2,"back":"答え：is\nMost of the furniture in this room is old.\nコツ：furniture（家具）は数えられない物 → 1つあつかいで is。\n（本冊436）"},{"id":"k437a","category":"is か are か（～のほとんど・～分の1）","front":"「そのケーキの3分の2は、もう食べられてしまった。」\nTwo thirds of the cake ＿＿＿ already been eaten.","options":["have","has","is","are"],"answer":1,"back":"答え：has\nTwo thirds of the cake has already been eaten.\nコツ：of の後ろの the cake（1つ）に合わせて has。\n（本冊437）"},{"id":"k437b","category":"is か are か（～のほとんど・～分の1）","front":"「その町の人の3分の2は、車を持っている。」\nTwo thirds of the people in the town ＿＿＿ cars.","options":["has","is","does","have"],"answer":3,"back":"答え：have\nTwo thirds of the people in the town have cars.\nコツ：of の後ろの the people（人たち）に合わせて have。\n（本冊437）"},{"id":"k438a","category":"is か are か（～のほとんど・～分の1）","front":"「私のおこづかいの30パーセントは、おかしに使われた。」\nThirty percent of my allowance ＿＿＿ spent on snacks.","options":["was","were","are","have"],"answer":0,"back":"答え：was\nThirty percent of my allowance was spent on snacks.\nコツ：of の後ろの allowance（おこづかい＝お金）は1つあつかい → was。\n（本冊438）"},{"id":"k438b","category":"is か are か（～のほとんど・～分の1）","front":"まちがっている言葉はどれ？\n①About 20 percent ②of the students in our school ③is ④from other cities.","options":["About","of","is","from"],"answer":2,"back":"答え：③ is → are\nAbout 20 percent of the students in our school are from other cities.\nコツ：of の後ろの students（2人以上）に合わせて are。\n（本冊438）"},{"id":"k439a","category":"is か are か（There is ／ There are）","front":"「この公園には、木がたくさんある。」\nThere ＿＿＿ a lot of trees in this park.","options":["is","are","be","has"],"answer":1,"back":"答え：are\nThere are a lot of trees in this park.\nコツ：There の文は後ろを見る。a lot of trees（たくさんの木）なので are。\n（本冊439）"},{"id":"k439b","category":"is か are か（There is ／ There are）","front":"「去年からずっと、この町には新しい店がたくさんある。」\nSince last year, there ＿＿＿ many new shops in this town.","options":["has been","was","is","have been"],"answer":3,"back":"答え：have been\nSince last year, there have been many new shops in this town.\nコツ：Since（～から今まで）なので have been。shops は2つ以上なので has ではない。\n（本冊439）"},{"id":"k440a","category":"is か are か（There is ／ There are）","front":"「雪が多ければ多いほど、子どもたちは喜ぶ。」\nThe more snow there ＿＿＿, the happier the children are.","options":["are","am","is","has"],"answer":2,"back":"答え：is\nThe more snow there is, the happier the children are.\nコツ：snow（雪）は数えられない物 → 1つあつかいで is。\n（本冊440）"},{"id":"k440b","category":"is か are か（There is ／ There are）","front":"まちがっている言葉はどれ？\nThere ①are ②no milk ③left ④in the fridge.","options":["are","no","left","in"],"answer":0,"back":"答え：① are → is\nThere is no milk left in the fridge.\nコツ：milk（牛乳）は数えられない物 → 1つあつかいで is。\n（本冊440）"},{"id":"k441a","category":"is か are か（the number of ／ a number of）","front":"「スマホを持っている子どもの数は、増えている。」\nThe number of children who have smartphones ＿＿＿ increasing.","options":["are","am","be","is"],"answer":3,"back":"答え：is\nThe number of children who have smartphones is increasing.\nコツ：The number of ～ は「～の数」。数は1つなので is。children につられない。\n（本冊441）"},{"id":"k441b","category":"is か are か（the number of ／ a number of）","front":"「この町に来る人の数は、去年から増えた。」\nThe number of people visiting this town ＿＿＿ increased since last year.","options":["has","have","is","are"],"answer":0,"back":"答え：has\nThe number of people visiting this town has increased since last year.\nコツ：The number of ～（～の数）は1つの話 → has。people につられない。\n（本冊441）"},{"id":"k442a","category":"is か are か（the number of ／ a number of）","front":"「たくさんの人がそのパーティーに招待された。」\nA number of people ＿＿＿ invited to the party.","options":["was","is","were","has"],"answer":2,"back":"答え：were\nA number of people were invited to the party.\nコツ：a number of ～ ＝「たくさんの～」。people（人たち）なので were。\n（本冊442）"},{"id":"k442b","category":"is か are か（the number of ／ a number of）","front":"「今日はたくさんの生徒が休んでいる。」\nA number of students ＿＿＿ absent today.","options":["is","are","was","has"],"answer":1,"back":"答え：are\nA number of students are absent today.\nコツ：a number of ～ ＝「たくさんの～」。students（2人以上）なので are。\n（本冊442）"},{"id":"k443a","category":"is か are か（国やグループの名前）","front":"「アメリカは大きな国だ。」\nThe United States ＿＿＿ a big country.","options":["is","are","were","have"],"answer":0,"back":"答え：is\nThe United States is a big country.\nコツ：The United States（アメリカ）は s がついていても1つの国 → is。\n（本冊443）"},{"id":"k443b","category":"is か are か（国やグループの名前）","front":"「国連の本部はニューヨークにある。」\nThe United Nations ＿＿＿ its main office in New York.","options":["have","is","are","has"],"answer":3,"back":"答え：has\nThe United Nations has its main office in New York.\nコツ：The United Nations（国連）は s がついていても1つのグループ → has。\n（本冊443）"},{"id":"k444a","category":"is か are か（時間・お金のまとまり）","front":"「10分では、宿題を終えるのに足りない。」\nTen minutes ＿＿＿ not enough time to finish my homework.","options":["are","is","have","be"],"answer":1,"back":"答え：is\nTen minutes is not enough time to finish my homework.\nコツ：「10分」はひとまとまりの時間 → 1つあつかいで is。\n（本冊444）"},{"id":"k444b","category":"is か are か（時間・お金のまとまり）","front":"「このTシャツに20ドルは高すぎる。」\nTwenty dollars ＿＿＿ too much for this T-shirt.","options":["are","am","is","have"],"answer":2,"back":"答え：is\nTwenty dollars is too much for this T-shirt.\nコツ：「20ドル」はひとまとまりの金額 → 1つあつかいで is。\n（本冊444）"},{"id":"k445a","category":"is か are か（the rich ＝ お金持ちの人たち）","front":"「お金持ちの人たちが、いつも幸せとはかぎらない。」\nThe rich ＿＿＿ not always happy.","options":["is","am","be","are"],"answer":3,"back":"答え：are\nThe rich are not always happy.\nコツ：the rich ＝ お金持ちの人たち（2人以上）→ are。\n（本冊445）"},{"id":"k445b","category":"is か are か（the rich ＝ お金持ちの人たち）","front":"まちがっている言葉はどれ？\nThe elderly in this town ①often ②enjoys ③walking ④in the park.","options":["often","enjoys","walking","in"],"answer":1,"back":"答え：② enjoys → enjoy\nThe elderly in this town often enjoy walking in the park.\nコツ：the elderly ＝ お年寄りの人たち（2人以上）→ s なしの enjoy。\n（本冊445）"},{"id":"k446a","category":"is か are か（who の前の人に合わせる）","front":"「その事故でけがをした人たちは、今、病院にいる。」\nThe people who ＿＿＿ hurt in the accident are now in the hospital.","options":["were","was","is","has"],"answer":0,"back":"答え：were\nThe people who were hurt in the accident are now in the hospital.\nコツ：who のすぐ前の The people（人たち）に合わせて were。\n（本冊446）"},{"id":"k446b","category":"is か are か（who の前の人に合わせる）","front":"まちがっている言葉はどれ？\nI know ①some boys who ②is ③good at ④soccer.","options":["some","is","good","soccer"],"answer":1,"back":"答え：② is → are\nI know some boys who are good at soccer.\nコツ：who のすぐ前の boys（2人以上）に合わせて are。\n（本冊446）"},{"id":"k447a","category":"is か are か（間に説明がはさまる）","front":"「ネコについての本は、机の上にある。」\nThe book about cats ＿＿＿ on the desk.","options":["are","were","is","have"],"answer":2,"back":"答え：is\nThe book about cats is on the desk.\nコツ：about cats はおまけの説明。前の The book（1冊）に合わせて is。\n（本冊447）"},{"id":"k447b","category":"is か are か（間に説明がはさまる）","front":"まちがっている言葉はどれ？\nThis year, the price of ①these ②vegetables ③have ④gone up.","options":["these","vegetables","have","gone"],"answer":2,"back":"答え：③ have → has\nThis year, the price of these vegetables has gone up.\nコツ：of these vegetables はおまけの説明。前の the price（ねだん＝1つ）に合わせて has。\n（本冊447）"}]},{"id":"ronpyo-448","group":"論理・表現 第11〜13章（12月期末）","title":"論表 質問の文（本冊448〜474と同じ文法）","subject":"論理・表現","order":1.8,"version":1,"cards":[{"id":"k448","category":"How＋〜 の聞き方","front":"「夏休みはどうやって過ごしたの？」\n＿＿＿ did you spend your summer vacation?","options":["What","Who","How","Which"],"answer":2,"back":"答え：How\nHow did you spend your summer vacation?\nコツ：「どうやって」は How。後ろの spend your summer vacation で文はもう全部そろっているので、「何」の What は入らない。\n（本冊448）"},{"id":"k449","category":"How＋〜 の聞き方","front":"「このかばんはいくらするの？」\nHow ＿＿＿ does this bag cost?","options":["much","many","long","often"],"answer":0,"back":"答え：much\nHow much does this bag cost?\nコツ：「いくら（ねだん）」は How much。How many は「いくつ（数）」を聞くとき。\n（本冊449）"},{"id":"k450","category":"How＋〜 の聞き方","front":"「どのくらいジムに行ってるの？」「週に2、3回だよ。」\nKen: How ＿＿＿ do you go to the gym?\nMai: Two or three times a week.","options":["long","many","far","often"],"answer":3,"back":"答え：often\nHow often do you go to the gym?\nコツ：答えが「週に2、3回」。回数を聞くときは How often（どのくらいよく）。\n（本冊450）"},{"id":"k451","category":"How＋〜 の聞き方","front":"「駅からあなたの学校まで、どのくらい遠いの？」\nHow ＿＿＿ is it from the station to your school?","options":["long","far","much","soon"],"answer":1,"back":"答え：far\nHow far is it from the station to your school?\nコツ：from 〜 to …（〜から…まで）の「遠さ」を聞くのは How far。How long は時間や長さ。\n（本冊451）"},{"id":"k452","category":"How＋〜 の聞き方","front":"「家から学校まで歩いてどのくらいかかる？」\n＿＿＿ to walk from your house to school?","options":["How long it takes you","How long you does it take","How long does it take you","How does it take you long"],"answer":2,"back":"答え：How long does it take you\nHow long does it take you to walk from your house to school?\nコツ：「どのくらい時間がかかる」は How long → does it take → you の順。ふつうの質問なので does が前。\n（本冊452）"},{"id":"k453","category":"How＋〜 の聞き方","front":"「映画はあとどのくらいで始まるの？」\nHow ＿＿＿ will the movie start?","options":["soon","long","fast","far"],"answer":0,"back":"答え：soon\nHow soon will the movie start?\nコツ：「あとどのくらいで」は How soon（soon ＝ もうすぐ）。How long は「どのくらいの間」。\n（本冊453）"},{"id":"k454","category":"文の中に入った質問","front":"「ここから海までどのくらい遠いのかなあ。」\nI wonder ＿＿＿ from here to the beach.","options":["how far is it","it is how far","how is it far","how far it is"],"answer":3,"back":"答え：how far it is\nI wonder how far it is from here to the beach.\nコツ：I wonder（〜かなあ）のあとに入った質問は、ふつうの文の順番（it is）にする。\n（本冊454）"},{"id":"k455","category":"文の中に入った質問","front":"「君に出会っていなかったら、ぼくの人生はどんなにちがっていただろうと、ときどき考える。」\nI sometimes think about ＿＿＿ if I had not met you.","options":["how different would my life have been","how different my life would have been","how my life different would have been","my life how different would have been"],"answer":1,"back":"答え：how different my life would have been\nI sometimes think about how different my life would have been if I had not met you.\nコツ：「どんなにちがう」は how different で1かたまり。そのあとは、ふつうの文の順番（my life would have been）。\n（本冊455）"},{"id":"k456","category":"Do you know 〜? と What do you think 〜?","front":"「空港行きのバスがいつ出るか知ってる？」\nDo you know ＿＿＿ for the airport?","options":["when the bus leaves","when does the bus leave","when leaves the bus","the bus when leaves"],"answer":0,"back":"答え：when the bus leaves\nDo you know when the bus leaves for the airport?\nコツ：Do you know のあとに入った質問は、ふつうの文の順番（the bus leaves）。\n（本冊456）"},{"id":"k457","category":"Do you know 〜? と What do you think 〜?","front":"「おもちは何から作られていると思う？」\n＿＿＿ made from?","options":["Do you think what mochi is","What do you think is mochi","What do you think mochi is","Do you think what is mochi"],"answer":2,"back":"答え：What do you think mochi is\nWhat do you think mochi is made from?\nコツ：「何だと思う？」と中身を聞くので What が一番前。do you think のあとは、ふつうの順番（mochi is）。\n（本冊457）"},{"id":"k458","category":"「〜しなかったの？」への答え方","front":"「宿題やらなかったの？」「ううん、やったよ。昨日の夜に終わらせた。」\nKen: Didn't you do your homework?\nMai: ＿＿＿ I finished it last night.","options":["No, I did.","No, I didn't.","Yes, I didn't.","Yes, I did."],"answer":3,"back":"答え：Yes, I did.\nYes, I did. I finished it last night.\nコツ：日本語の「ううん」につられない。やったなら Yes, I did. やらなかったなら No, I didn't.\n（本冊458）"},{"id":"k459","category":"〜ですよね？（文の最後）","front":"「つかれてないよね？」\nYou aren't tired, ＿＿＿?","options":["aren't you","are you","do you","don't you"],"answer":1,"back":"答え：are you\nYou aren't tired, are you?\nコツ：文の最後の 〜ね？ は、前が not ありなら not なしで聞く。aren't → are you。\n（本冊459）"},{"id":"k460","category":"〜ですよね？（文の最後）","front":"「ケンが言ったことは本当だよね？」\nWhat Ken said is true, ＿＿＿?","options":["isn't it","isn't he","didn't he","is it"],"answer":0,"back":"答え：isn't it\nWhat Ken said is true, isn't it?\nコツ：本当なのは「ケンが言ったこと」。「こと」は it で受ける。前が is で not なしなので isn't it。\n（本冊460）"},{"id":"k461","category":"〜ですよね？（文の最後）","front":"「お昼はピザを食べようよ。」\nLet's have pizza for lunch, ＿＿＿?","options":["will you","don't we","shall we","do we"],"answer":2,"back":"答え：shall we\nLet's have pizza for lunch, shall we?\nコツ：Let's 〜（〜しよう）の文の最後は、いつも shall we? と決まっている。\n（本冊461）"},{"id":"k462","category":"〜ですよね？（文の最後）","front":"「この近くにコンビニがあるよね？」\nThere is a convenience store near here, ＿＿＿?","options":["isn't it","is there","doesn't it","isn't there"],"answer":3,"back":"答え：isn't there\nThere is a convenience store near here, isn't there?\nコツ：There is 〜 の文の最後は there を使う。前が is で not なしなので isn't there。\n（本冊462）"},{"id":"k463","category":"きまった聞き方","front":"「うちの部では、どこの出身かは大事じゃない。」\nIn our club, it is not important ＿＿＿.","options":["where do you come from","where you come from","where you are come from","where come you from"],"answer":1,"back":"答え：where you come from\nIn our club, it is not important where you come from.\nコツ：「どこの出身か」は where you come from。文の途中に入った質問なので、ふつうの順番（you come）。\n（本冊463）"},{"id":"k464","category":"きまった聞き方","front":"「この写真を見ると、昔の東京がどんなふうだったかわかる。」\nThis photo shows us ＿＿＿ long ago.","options":["what Tokyo was like","how Tokyo was like","what was Tokyo like","how was Tokyo like"],"answer":0,"back":"答え：what Tokyo was like\nThis photo shows us what Tokyo was like long ago.\nコツ：「どんなふう」は what 〜 like。how と like はいっしょに使わない。文の途中なので Tokyo was の順番。\n（本冊464）"},{"id":"k465","category":"きまった聞き方","front":"「一人暮らしがどんな感じなのか、まったくわからなかった。」\nI had no idea ＿＿＿ to live alone.","options":["what would it be like","how it would be like","what it would be like","how would it be like"],"answer":2,"back":"答え：what it would be like\nI had no idea what it would be like to live alone.\nコツ：「〜するのってどんな感じ」は what it is like to 〜。how と like はいっしょに使わない。文の途中なので it would be の順番。\n（本冊465）"},{"id":"k466","category":"きまった聞き方","front":"「新しい先生のこと、どう思う？」\n＿＿＿ do you think of our new teacher?","options":["How","Which","Where","What"],"answer":3,"back":"答え：What\nWhat do you think of our new teacher?\nコツ：日本語は「どう思う」でも、英語は What do you think of 〜?。How は使わない。\n（本冊466）"},{"id":"k467","category":"きまった聞き方","front":"「子どものころに乗っていた自転車は、どうなったのかなあ。」\nI wonder what has ＿＿＿ of the bike I rode as a kid.","options":["happened","become","gone","made"],"answer":1,"back":"答え：become\nI wonder what has become of the bike I rode as a kid.\nコツ：「〜はどうなったか」は what has become of 〜。of とセットなのは become（happened なら to）。\n（本冊467）"},{"id":"k468","category":"きまった聞き方","front":"「どうしてパーティーに来なかったの？」\nHow come ＿＿＿ to the party?","options":["didn't you come","did you not come","you didn't come","you not came"],"answer":2,"back":"答え：you didn't come\nHow come you didn't come to the party?\nコツ：How come（どうして）のあとは、ふつうの文の順番（you didn't come）。Why なら Why didn't you come。\n（本冊468）"},{"id":"k469","category":"きまった聞き方","front":"「何をしにここへ来たの？」\nWhat did you come here ＿＿＿?","options":["for","to","why","because"],"answer":0,"back":"答え：for\nWhat did you come here for?\nコツ：What 〜 for? で「何のために」。最後の for を忘れない。\n（本冊469）"},{"id":"k470","category":"〜しませんか？のさそい方","front":"「頭がすごくいたいんだ。」「病院に行ったらどう？」\nKen: I have a bad headache.\nMai: ＿＿＿ see a doctor?","options":["Why do you","What don't you","How don't you","Why don't you"],"answer":3,"back":"答え：Why don't you\nWhy don't you see a doctor?\nコツ：Why don't you 〜? ＝「〜したらどう？」と相手にすすめる言い方。\n（本冊470）"},{"id":"k471","category":"〜しませんか？のさそい方","front":"「今度の土曜日、いっしょに映画を見に行かない？」\n＿＿＿ see a movie this Saturday?","options":["Why we don't go to","Why don't we go to","Why don't go we to","Don't we why go to"],"answer":1,"back":"答え：Why don't we go to\nWhy don't we go to see a movie this Saturday?\nコツ：Why don't we 〜? ＝「（いっしょに）〜しない？」。we なので自分も入る。Why → don't → we の順。\n（本冊471）"},{"id":"k472","category":"〜しませんか？のさそい方","front":"「次の日曜日、みんなで海に行くのはどう？」\nWhat about ＿＿＿ the beach next Sunday?","options":["going to","go to","to go to","went to"],"answer":0,"back":"答え：going to\nWhat about going to the beach next Sunday?\nコツ：What about のあとは -ing の形（going）。How about 〜ing と同じ意味。\n（本冊472）"},{"id":"k473","category":"？なのに「〜ない」の意味","front":"「明日の天気がどうなるかなんて、だれにもわからないよ。」\n＿＿＿ knows what the weather will be like tomorrow?","options":["Why","Which","Who","How"],"answer":2,"back":"答え：Who\nWho knows what the weather will be like tomorrow?\nコツ：Who knows? ＝「だれが知ってる？」→「だれも知らない」。Nobody knows と同じ意味。\n（本冊473）"},{"id":"k474","category":"？なのに「〜ない」の意味","front":"「今さらテストのことを心配して、何になるの？」\n＿＿＿ about the test now?","options":["What the use is of worrying","What is the use worrying of","What use is the of worrying","What is the use of worrying"],"answer":3,"back":"答え：What is the use of worrying\nWhat is the use of worrying about the test now?\nコツ：What is the use of 〜ing? ＝「〜して何になるの？（何にもならない）」。of のあとは -ing の形。\n（本冊474）"}]},{"id":"ronpyo-a1","group":"論理・表現 第11〜13章（12月期末）","title":"論表 予想問題 A① 比較（4択）","subject":"論理・表現","order":2,"version":2,"cards":[{"id":"q01","category":"〜と同じくらい","front":"「兄はぼくと同じくらい速く泳げる。」\nMy brother can swim as ＿＿＿ as I can.","options":["faster","fast","fastest","more fast"],"answer":1,"back":"答え：fast\nMy brother can swim as fast as I can.\nコツ：as と as にはさまれたら、もとの形（-er や -est がつかない形）。\n（本冊374〜375）"},{"id":"q02","category":"〜ほど…じゃない","front":"「このかばんは、見た目ほど重くない。」\nThis bag is not as heavy ＿＿＿ it looks.","options":["than","so","that","as"],"answer":3,"back":"答え：as\nThis bag is not as heavy as it looks.\nコツ：前に as があるので、後ろも as。as 〜 as はペア。\n（本冊376）"},{"id":"q03","category":"〜倍","front":"「新しい体育館は、前のの3倍の広さだ。」\nOur new gym is three times ＿＿＿ the old one.","options":["as large as","larger as","as larger than","large as"],"answer":0,"back":"答え：as large as\nOur new gym is three times as large as the old one.\nコツ：three times（3倍）のあとは as 〜 as の形。まん中はもとの形（-er がつかない）。\n（本冊378〜381）"},{"id":"q04","category":"〜倍","front":"「このタブレットは、あのノートパソコンの半分の重さだ。」\nThis tablet is half ＿＿＿ of that laptop.","options":["as weight","weight as","the weight","the heavy"],"answer":2,"back":"答え：the weight\nThis tablet is half the weight of that laptop.\nコツ：half（半分）のあと、後ろに of があるので the weight（重さ）。\n（本冊382〜383）"},{"id":"q05","category":"できるだけ〜","front":"「できるだけ早く、メールに返事してね。」\nPlease answer the email as soon as ＿＿＿.","options":["possible","you possible","possibly","can"],"answer":0,"back":"答え：possible\nPlease answer the email as soon as possible.\nコツ：as soon as possible ＝「できるだけ早く」。セットで覚える。\n（本冊384〜385）"},{"id":"q06","category":"〜さえしないで","front":"「彼女は、さよならさえ言わずに出ていった。」\nShe left without so much as ＿＿＿ goodbye.","options":["said","saying","say","to say"],"answer":1,"back":"答え：saying\nShe left without so much as saying goodbye.\nコツ：without（〜しないで）のあとは -ing の形。so much as は「〜さえ」。\n（本冊388）"},{"id":"q07","category":"〜も（多い）","front":"「その小さなコンサートに、300人もの人が来た。」\nAs ＿＿＿ as 300 people came to the small concert.","options":["much","most","more","many"],"answer":3,"back":"答え：many\nAs many as 300 people came to the small concert.\nコツ：people（人）は数えられるので many。as many as 300 ＝「300人も」。\n（本冊391）"},{"id":"q08","category":"たった〜（少ない）","front":"「このシャツは、たった5ドルで買える。」\nYou can buy this shirt for as ＿＿＿ as five dollars.","options":["many","much","little","less"],"answer":2,"back":"答え：little\nYou can buy this shirt for as little as five dollars.\nコツ：five dollars は「金額」＝量なので little。as little as ＝「たった〜」。\n（本冊392）"},{"id":"q09","category":"ずっと〜","front":"「この映画は、1作目よりずっとおもしろい。」\nThis movie is ＿＿＿ more exciting than the first one.","options":["very","much","so","too"],"answer":1,"back":"答え：much\nThis movie is much more exciting than the first one.\nコツ：more 〜 than（〜より）を「ずっと」と強めるのは much。very は使えない。\n（本冊394）"},{"id":"q10","category":"2つのうち〜なほう","front":"「ケンは、2人の男の子のうち背が高いほうだ。」\nKen is the taller ＿＿＿ the two boys.","options":["of","in","among","than"],"answer":0,"back":"答え：of\nKen is the taller of the two boys.\nコツ：the two（2人）があったら of。「2人のうちの」＝ of the two。\n（本冊398）"},{"id":"q11","category":"〜すればするほど","front":"「練習すればするほど、うまくなるよ。」\nThe ＿＿＿ you practice, the better you will play.","options":["much","most","more","many"],"answer":2,"back":"答え：more\nThe more you practice, the better you will play.\nコツ：後ろが the better（-er の形）なので、前も the more。The -er, the -er で「〜ほど〜」。\n（本冊399〜400）"},{"id":"q12","category":"だからなおさら","front":"「正直だから、私は彼がなおさら好きだ。」\nI like him all the ＿＿＿ for his honesty.","options":["best","good","well","better"],"answer":3,"back":"答え：better\nI like him all the better for his honesty.\nコツ：all the のあとは -er の形（better）。for 〜 で「〜だから、なおさら」。\n（本冊401）"},{"id":"q13","category":"たった〜","front":"「そこまで歩くのに、たった10分しかかからなかった。」\nIt took me no ＿＿＿ than ten minutes to walk there.","options":["less","much","most","more"],"answer":3,"back":"答え：more\nIt took me no more than ten minutes to walk there.\nコツ：no more than ＝「たった〜」（少ない）。no less than は「〜も」（多い）。\n（本冊405〜406）"},{"id":"q14","category":"〜でないのと同じ","front":"「コウモリが鳥でないのは、クジラが魚でないのと同じだ。」\nA bat is no more a bird ＿＿＿ a whale is a fish.","options":["than","that","as","so"],"answer":0,"back":"答え：than\nA bat is no more a bird than a whale is a fish.\nコツ：前に more があるので、ペアは than。\n（本冊407〜408）"},{"id":"q15","category":"〜するほどバカじゃない","front":"「彼は、そんな話を信じるほどバカじゃない。」\nHe knows ＿＿＿ than to believe such a story.","options":["well","better","good","best"],"answer":1,"back":"答え：better\nHe knows better than to believe such a story.\nコツ：後ろに than があるので -er の形の better。know better than to 〜 ＝「〜するほどバカじゃない」。\n（本冊411）"},{"id":"q16","category":"まして〜ない","front":"「彼女はフランス語が話せない。ましてロシア語なんて無理だ。」\nShe can't speak French, ＿＿＿ Russian.","options":["much more","no less","much less","any more"],"answer":2,"back":"答え：much less\nShe can't speak French, much less Russian.\nコツ：前が can't（〜ない）の文なので much less ＝「まして〜ない」。\n（本冊412）"},{"id":"q17","category":"than じゃなく to","front":"「この新しい機種は、古いのよりすぐれている。」\nThis new model is superior ＿＿＿ the old one.","options":["to","of","than","for"],"answer":0,"back":"答え：to\nThis new model is superior to the old one.\nコツ：superior（すぐれている）は than ではなく to を使う。\n（本冊414・416）"},{"id":"q18","category":"than じゃなく to","front":"「バスに乗るより、歩くほうが好きだ。」\nI prefer walking ＿＿＿ taking the bus.","options":["than","with","to","for"],"answer":2,"back":"答え：to\nI prefer walking to taking the bus.\nコツ：prefer A to B ＝「BよりAが好き」。prefer は than ではなく to。\n（本冊415）"},{"id":"q19","category":"〜の中でいちばん","front":"「エベレストは世界でいちばん高い山だ。」\nMt. Everest is the highest mountain ＿＿＿ the world.","options":["of","in","at","among"],"answer":1,"back":"答え：in\nMt. Everest is the highest mountain in the world.\nコツ：the world（世界）のような「場所」の中でいちばんなら in。\n（本冊417・420）"},{"id":"q20","category":"ダントツで〜","front":"「これは、今まで食べた中でダントツにおいしいピザだ。」\nThis is ＿＿＿ the best pizza I have ever eaten.","options":["very","more","so","by far"],"answer":3,"back":"答え：by far\nThis is by far the best pizza I have ever eaten.\nコツ：the best（いちばん）を「ダントツで」と強めるのは by far。very は the の前に置けない。\n（本冊418〜419）"},{"id":"q21","category":"いちばん〜なものの1つ","front":"「東京は、世界でいちばん大きい都市の1つだ。」\nTokyo is one of the largest ＿＿＿ in the world.","options":["city","a city","cities","the city"],"answer":2,"back":"答え：cities\nTokyo is one of the largest cities in the world.\nコツ：one of the 〜（〜のうちの1つ）のあとは -s がついた形。city → cities。\n（本冊421）"},{"id":"q22","category":"ほかのだれも〜ない","front":"「クラスで、ユミより背の高い生徒はほかにいない。」\nNo other student in her class is ＿＿＿ than Yumi.","options":["taller","tall","tallest","as tall"],"answer":0,"back":"答え：taller\nNo other student in her class is taller than Yumi.\nコツ：後ろに than があるので -er の形の taller。\n（本冊425〜427）"},{"id":"q23","category":"ほかのどんなものより","front":"「時間は、ほかのどんなものより大切だ。」\nTime is more precious than anything ＿＿＿.","options":["other","more","any","else"],"answer":3,"back":"答え：else\nTime is more precious than anything else.\nコツ：anything に「ほかの」をつけるなら後ろに else。anything else ＝「ほかの何か」。\n（本冊430）"},{"id":"q24","category":"ほかのどの〜より","front":"「琵琶湖は、日本のほかのどの湖よりも大きい。」\nLake Biwa is larger than any other ＿＿＿ in Japan.","options":["lakes","lake","the lake","a lake"],"answer":1,"back":"答え：lake\nLake Biwa is larger than any other lake in Japan.\nコツ：any other（ほかのどの）のあとは -s をつけない形。lake のまま。\n（本冊429）"}]},{"id":"ronpyo-a2","group":"論理・表現 第11〜13章（12月期末）","title":"論表 予想問題 A② 一致・疑問文（4択）","subject":"論理・表現","order":3,"version":2,"cards":[{"id":"q01","category":"is か are か","front":"「父も母も先生だ。」\nBoth my father and my mother ＿＿＿ teachers.","options":["is","are","has","was"],"answer":1,"back":"答え：are\nBoth my father and my mother are teachers.\nコツ：Both（2人とも）で父と母の2人。2人以上なら are。\n（本冊431）"},{"id":"q02","category":"was か were か","front":"「生徒たちだけでなく、先生もわくわくしていた。」\nNot only the students but also their teacher ＿＿＿ excited.","options":["were","have been","are","was"],"answer":3,"back":"答え：was\nNot only the students but also their teacher was excited.\nコツ：but also のすぐ後ろ（their teacher＝1人）に合わせる。1人で昔のことなので was。\n（本冊432）"},{"id":"q03","category":"has か have か","front":"「君かトムのどちらかが、部屋をそうじしないといけない。」\nEither you or Tom ＿＿＿ to clean the room.","options":["have","are","has","were"],"answer":2,"back":"答え：has\nEither you or Tom has to clean the room.\nコツ：or のすぐ後ろの Tom（1人）に合わせて has。\n（本冊433〜434）"},{"id":"q04","category":"is か are か","front":"「友だちだけでなく、姉もお祭りに行く予定だ。」\nMy sister, as well as her friends, ＿＿＿ going to the festival.","options":["are","is","were","have"],"answer":1,"back":"答え：is\nMy sister, as well as her friends, is going to the festival.\nコツ：as well as 〜 はおまけ。文のはじめの My sister（1人）に合わせて is。\n（本冊435）"},{"id":"q05","category":"is か are か","front":"「この川の水のほとんどは、よごれている。」\nMost of the water in this river ＿＿＿ polluted.","options":["is","were","are","have been"],"answer":0,"back":"答え：is\nMost of the water in this river is polluted.\nコツ：of のあとの water（水）は数えられない物なので is。\n（本冊436）"},{"id":"q06","category":"was か were か","front":"「生徒の3分の2が、その計画に反対だった。」\nTwo thirds of the students ＿＿＿ against the plan.","options":["was","is","were","has"],"answer":2,"back":"答え：were\nTwo thirds of the students were against the plan.\nコツ：of のあとの students（生徒たち＝2人以上）に合わせる。2人以上で昔のことなので were。\n（本冊437〜438）"},{"id":"q07","category":"is か are か","front":"「ホールには、いすがたくさんある。」\nThere ＿＿＿ a lot of chairs in the hall.","options":["is","was","has","are"],"answer":3,"back":"答え：are\nThere are a lot of chairs in the hall.\nコツ：There のあとは、後ろの chairs（いすがたくさん）に合わせて are。\n（本冊439〜440）"},{"id":"q08","category":"is か are か","front":"「観光客の数は、毎年ふえている。」\nThe number of tourists ＿＿＿ increasing every year.","options":["are","have","were","is"],"answer":3,"back":"答え：is\nThe number of tourists is increasing every year.\nコツ：The number of 〜 ＝「〜の数」。数は1つなので is。\n（本冊441）"},{"id":"q09","category":"was か were か","front":"「図書館から、たくさんの本がぬすまれた。」\nA number of books ＿＿＿ stolen from the library.","options":["were","was","has","is"],"answer":0,"back":"答え：were\nA number of books were stolen from the library.\nコツ：A number of 〜 ＝「たくさんの〜」。本がたくさん（2つ以上）なので were。\n（本冊442）"},{"id":"q10","category":"is か are か","front":"「10キロは、歩くには長い道のりだ。」\nTen kilometers ＿＿＿ a long way to walk.","options":["are","is","were","have"],"answer":1,"back":"答え：is\nTen kilometers is a long way to walk.\nコツ：10キロ・3時間・100円のような「きょり・時間・お金」は1つのかたまりなので is。\n（本冊444）"},{"id":"q11","category":"is か are か","front":"「若い人たちは、新しい技術に興味をもつことが多い。」\nThe young ＿＿＿ often interested in new technology.","options":["is","was","are","has"],"answer":2,"back":"答え：are\nThe young are often interested in new technology.\nコツ：The young ＝ young people（若い人たち）。2人以上なので are。\n（本冊445）"},{"id":"q12","category":"How＋〜 の聞き方","front":"「どのくらいよく歯医者に行くの？ — 年に2回だよ。」\n＿＿＿ do you go to the dentist? — Twice a year.","options":["How often","How long","How far","How soon"],"answer":0,"back":"答え：How often\nHow often do you go to the dentist? — Twice a year.\nコツ：答えが Twice（2回）＝回数なので How often。\n（本冊450）"},{"id":"q13","category":"How＋〜 の聞き方","front":"「家から駅まで、どのくらいの距離？ — 2キロくらい。」\n＿＿＿ is it from your house to the station? — About two kilometers.","options":["How long","How much","How far","How often"],"answer":2,"back":"答え：How far\nHow far is it from your house to the station? — About two kilometers.\nコツ：答えが two kilometers（きょり）なので How far。\n（本冊451）"},{"id":"q14","category":"文の中の where","front":"「彼女はどこに住んでいるのかなあ。」\nI wonder ＿＿＿.","options":["where does she live","where she lives","she lives where","does she live where"],"answer":1,"back":"答え：where she lives\nI wonder where she lives.\nコツ：I wonder のあとは where のあとにふつうの文（she lives）。does は使わない。\n（本冊454）"},{"id":"q15","category":"だれが〜と思う？","front":"「だれが試合に勝つと思う？」\n＿＿＿ do you think will win the game?","options":["Whose","Do you know who","Whom","Who"],"answer":3,"back":"答え：Who\nWho do you think will win the game?\nコツ：「だれが」とたずねるので Who。Who を文のいちばん前に出す。\n（本冊457）"},{"id":"q16","category":"Yes か No か","front":"「コーヒー好きじゃないの？ — うん、好きじゃない。全然飲まないよ。」\nDon't you like coffee? — ＿＿＿ I don't drink it at all.","options":["Yes, I do.","Yes, I don't.","No, I don't.","No, I do."],"answer":2,"back":"答え：No, I don't.\nDon't you like coffee? — No, I don't. I don't drink it at all.\nコツ：好きじゃない（don't）なら英語は No。日本語の「うん」につられない。\n（本冊458）"},{"id":"q17","category":"〜だよね？ の付け方","front":"「宿題、まだ終わってないよね？」\nYou haven't finished your homework, ＿＿＿?","options":["have you","did you","haven't you","do you"],"answer":0,"back":"答え：have you\nYou haven't finished your homework, have you?\nコツ：前が haven't（〜ない）なので、後ろは n't をとって have you。\n（本冊459）"},{"id":"q18","category":"〜だよね？ の付け方","front":"「ちょっと休もうよ、ね？」\nLet's take a break, ＿＿＿?","options":["will you","don't we","won't you","shall we"],"answer":3,"back":"答え：shall we\nLet's take a break, shall we?\nコツ：Let's（〜しよう）の文の「ね？」は shall we と決まっている。\n（本冊461）"},{"id":"q19","category":"〜したら？","front":"「先生にアドバイスをもらったら？」\n＿＿＿ don't you ask your teacher for advice?","options":["What","Why","How","Where"],"answer":1,"back":"答え：Why\nWhy don't you ask your teacher for advice?\nコツ：Why don't you 〜? ＝「〜したらどう？」。セットで覚える。\n（本冊470）"},{"id":"q20","category":"どんな人？","front":"「新しい先生って、どんな人？ — やさしくておもしろいよ。」\nWhat is the new teacher ＿＿＿? — She is kind and funny.","options":["as","like","about","for"],"answer":1,"back":"答え：like\nWhat is the new teacher like? — She is kind and funny.\nコツ：What is 〜 like? ＝「〜はどんな人（物）？」。最後の like がポイント。\n（本冊464）"},{"id":"q21","category":"何のために？","front":"「何のために街へ行ったの？」\nWhat did you go to the city ＿＿＿?","options":["of","to","than","for"],"answer":3,"back":"答え：for\nWhat did you go to the city for?\nコツ：What 〜 for? ＝「何のために？」。最後の for がポイント。\n（本冊469）"},{"id":"q22","category":"どうして〜なの？","front":"「どうして今朝おくれたの？」\n＿＿＿ come you were late this morning?","options":["How","Why","What","Where"],"answer":0,"back":"答え：How\nHow come you were late this morning?\nコツ：How come 〜? ＝「どうして〜？」。come とセットなのは How。\n（本冊468）"},{"id":"q23","category":"だれにも〜ない","front":"「何が起こるかなんて、だれにもわからない。」\n＿＿＿ knows what will happen.","options":["Everybody","Somebody","Nobody","Anybody"],"answer":2,"back":"答え：Nobody\nNobody knows what will happen.\nコツ：「だれにも〜ない」＝ Nobody。Who knows?（だれが知ってる？＝だれも知らない）も同じ意味。\n（本冊473）"}]},{"id":"ronpyo-b","group":"論理・表現 第11〜13章（12月期末）","title":"論表 予想問題 B 並べ替え","subject":"論理・表現","order":4,"version":3,"cards":[{"id":"q01","category":"～倍","front":"「この教室はあの教室の2倍の広さがある。」\nThis classroom is ＿＿＿ that one.\n正しい順番はどれ？","back":"答え：twice as large as\nThis classroom is twice as large as that one.\nコツ：「2倍」twice を一番前に。そのあと as large as。","options":["as large as twice","twice as large as","as twice large as","as large twice as"],"answer":1},{"id":"q02","category":"as ～ as","front":"「私は彼ほど多くのCDを持っていない。」\nI don't have ＿＿＿ he does.\n正しい順番はどれ？","back":"答え：as many CDs as\nI don't have as many CDs as he does.\nコツ：many CDs はくっつけたまま、as と as ではさむ。\n（本冊377）","options":["as CDs many as","as many as CDs","many as CDs as","as many CDs as"],"answer":3},{"id":"q03","category":"the ＋ -er の形","front":"「宿題を早く始めれば始めるほど、早く終わる。」\n＿＿＿ your homework, the sooner you will finish.\n正しい順番はどれ？","back":"答え：The sooner you start\nThe sooner you start your homework, the sooner you will finish.\nコツ：The sooner を先頭に。そのあと you start（だれが → する）。","options":["The sooner you start","The sooner start you","You start the sooner","The start you sooner"],"answer":0},{"id":"q04","category":"the ＋ -er の形","front":"「彼はまちがいもするけれど、それでも私は彼を尊敬している。」\nI respect him ＿＿＿ his mistakes.\n正しい順番はどれ？","back":"答え：none the less for\nI respect him none the less for his mistakes.\nコツ：none the less for ～ ＝「～があっても、それでも」。none → the → less → for の順。\n（本冊402）","options":["the none less for","none less the for","none the less for","for none the less"],"answer":2},{"id":"q05","category":"no less ～ than","front":"「ケンはお兄さんに負けないくらい頭がいい。」\nKen is ＿＿＿ his brother.\n正しい順番はどれ？","back":"答え：no less clever than\nKen is no less clever than his brother.\nコツ：no less ～ than ＝「～に負けないくらい」。no less → clever → than の順。\n（本冊409）","options":["no clever less than","no less clever than","less clever no than","no less than clever"],"answer":1},{"id":"q06","category":"「一番」の別の言い方","front":"「このクラスでリナほど速く泳ぐ生徒はいない。」\n＿＿＿ swims as fast as Rina.\n正しい順番はどれ？","back":"答え：No other student in this class\nNo other student in this class swims as fast as Rina.\nコツ：「ほかのどの生徒も～ない」は No other student。すぐ後ろに in this class。\n（本冊425）","options":["No other student in this class","No student other in this class","Other no student in this class","No other in this class student"],"answer":0},{"id":"q07","category":"一番（the most）","front":"「これは私が今まで見た中で一番わくわくする映画です。」\nThis is ＿＿＿ have ever seen.\n正しい順番はどれ？","back":"答え：the most exciting movie I\nThis is the most exciting movie I have ever seen.\nコツ：「一番～な」は the most ～。そのあと movie、最後に I。\n（本冊422〜423）","options":["the exciting most movie I","most the exciting movie I","the most movie exciting I","the most exciting movie I"],"answer":3},{"id":"q08","category":"文の中の質問","front":"「学校までどれくらい時間がかかるか知っていますか。」\nDo you know ＿＿＿ to get to school?\n正しい順番はどれ？","back":"答え：how long it takes\nDo you know how long it takes to get to school?\nコツ：Do you know のあとは、ふつうの文の順番（it takes）。takes it にはしない。\n（本冊452・456）","options":["how it takes long","how long takes it","how long it takes","long how it takes"],"answer":2},{"id":"q09","category":"文の中の質問","front":"「彼女はなぜ怒ったと思いますか。」\nWhy ＿＿＿ was angry?\n正しい順番はどれ？","back":"答え：do you think she\nWhy do you think she was angry?\nコツ：Why のすぐ後ろに do you think。そのあと she was angry。\n（本冊457）","options":["you do think she","do you think she","do she think you","she do you think"],"answer":1},{"id":"q10","category":"「どう思う？」","front":"「その映画についてどう思いますか。」\n＿＿＿ of the movie?\n正しい順番はどれ？","back":"答え：What do you think\nWhat do you think of the movie?\nコツ：「どう思う？」は What do you think of ～? 「どう」につられて How にしない。\n（本冊466）","options":["How do you think","What you do think","How you think do","What do you think"],"answer":3},{"id":"q11","category":"「何の役に立つの？」","front":"「そんなことで泣いて、何の役に立つの？」\nWhat ＿＿＿ crying about it?\n正しい順番はどれ？","back":"答え：is the use of\nWhat is the use of crying about it?\nコツ：What is the use of ～ing? ＝「～して何の役に立つの？（立たない）」。\n（本冊474）","options":["is the use of","the use is of","is of the use","use is the of"],"answer":0}]},{"id":"ronpyo-cd","group":"論理・表現 第11〜13章（12月期末）","title":"論表 予想問題 C・D 書きかえ・誤り指摘","subject":"論理・表現","order":5,"version":3,"cards":[{"id":"q01","category":"書きかえ","front":"上と下が同じ意味になるように、＿＿＿ に入る言葉は？\n上：This watch is not as expensive as that one.\n下：This watch is ＿①＿ ＿②＿ than that one.","back":"答え：① less ② expensive\nThis watch is less expensive than that one.\nコツ：not as ～ as（ほど～ない）＝ less ～ than。less は more の反対。\n（本冊395）","options":["① more ② expensive","① much ② expensive","① less ② expensive","① not ② expensive"],"answer":2},{"id":"q02","category":"書きかえ","front":"上と下が同じ意味になるように、＿＿＿ に入る言葉は？\n上：Lake Biwa is the largest lake in Japan.\n下：Lake Biwa is larger than ＿①＿ ＿②＿ lake in Japan.","back":"答え：① any ② other\nLake Biwa is larger than any other lake in Japan.\nコツ：「一番大きい」＝「ほかのどの湖よりも大きい」。ほかのどの ＝ any other。\n（本冊429）","options":["① any ② other","① all ② other","① other ② any","① any ② others"],"answer":0},{"id":"q03","category":"書きかえ","front":"上と下が同じ意味になるように、＿＿＿ に入る言葉は？\n上：I have only 300 yen.\n下：I have no ＿①＿ ＿②＿ 300 yen.","back":"答え：① more ② than\nI have no more than 300 yen.\nコツ：no more than ～ ＝「～しか（ない）」＝ only。\n（本冊405）","options":["① less ② than","① more ② as","① much ② than","① more ② than"],"answer":3},{"id":"q04","category":"書きかえ","front":"上と下が同じ意味になるように、＿＿＿ に入る言葉は？\n上：Mr. Sato is a scientist rather than a doctor.\n下：Mr. Sato is not so much a doctor ＿＿＿ a scientist.","back":"答え：as\nMr. Sato is not so much a doctor as a scientist.\nコツ：not so much ～ as … ＝「～というより、むしろ…」。much の相手は as。\n（本冊386）","options":["than","as","so","but"],"answer":1},{"id":"q05","category":"書きかえ","front":"上と下が同じ意味になるように、＿＿＿ に入る言葉は？\n上：Nobody knows what will happen tomorrow.\n下：＿＿＿ knows what will happen tomorrow?","back":"答え：Who\nWho knows what will happen tomorrow?\nコツ：「だれが知っているだろう？」＝「だれも知らない」。最後の ? がヒント。\n（本冊473）","options":["What","Where","Who","Why"],"answer":2},{"id":"q06","category":"書きかえ","front":"上と下が同じ意味になるように、＿＿＿ に入る言葉は？\n上：Why don't we play soccer?\n下：＿＿＿ play soccer.","back":"答え：Let's\nLet's play soccer.\nコツ：Why don't we ～? ＝「～しようよ」＝ Let's ～。\n（本冊471）","options":["Let's","Shall","Don't","Why"],"answer":0},{"id":"q07","category":"書きかえ","front":"上と下が同じ意味になるように、＿＿＿ に入る言葉は？\n上：It is no use worrying about the test.\n下：What is the ＿＿＿ of worrying about the test?","back":"答え：use\nWhat is the use of worrying about the test?\nコツ：It is no use ～ing（～してもむだ）＝ What is the use of ～ing?\n（本冊474）","options":["useful","help","using","use"],"answer":3},{"id":"q08","category":"まちがい探し","front":"まちがっている言葉が1つあります。どれ？\nThe number of ①students ②in this school ③have ④increased.","options":["①students","②in this school","③have","④increased"],"answer":2,"back":"答え：③ have → has\nThe number of students in this school has increased.\nコツ：the number of ～ は「～の数」。数は1つなので has。\n（本冊441）"},{"id":"q09","category":"まちがい探し","front":"まちがっている言葉が1つあります。どれ？\nMy mother, ①as well as ②my sisters, ③like ④watching movies.","options":["①as well as","②my sisters","③like","④watching movies"],"answer":2,"back":"答え：③ like → likes\nMy mother, as well as my sisters, likes watching movies.\nコツ：as well as ～ の文は、前の My mother が中心。お母さんは1人 → likes。\n（本冊435）"},{"id":"q10","category":"まちがい探し","front":"まちがっている言葉が1つあります。どれ？\nThis is ①one of ②the oldest ③temple ④in Kyoto.","options":["①one of","②the oldest","③temple","④in Kyoto"],"answer":2,"back":"答え：③ temple → temples\nThis is one of the oldest temples in Kyoto.\nコツ：one of（～のうちの1つ）は、たくさんある中の1つ → temples と s がつく。\n（本冊421）"},{"id":"q11","category":"まちがい探し","front":"まちがっている言葉が1つあります。どれ？\nHow ①long is it ②from your house ③to the station? — ④About two kilometers.","options":["①long","②from your house","③to the station","④About two kilometers"],"answer":0,"back":"答え：① long → far\nHow far is it from your house to the station? — About two kilometers.\nコツ：答えが「約2キロ」＝ 道のりの長さ。「どれくらい遠い？」は How far。\n（本冊451）"},{"id":"q12","category":"まちがい探し","front":"まちがっている言葉が1つあります。どれ？\nThis bag is ①very ②lighter ③than ④mine.","options":["①very","②lighter","③than","④mine"],"answer":0,"back":"答え：① very → much\nThis bag is much lighter than mine.\nコツ：lighter のような -er の形を強めるのは much。very は使えない。\n（本冊394）"},{"id":"q13","category":"まちがい探し","front":"まちがっている言葉が1つあります。どれ？\nThere ①are ②a lot of water ③in ④this bottle.","options":["①are","②a lot of water","③in","④this bottle"],"answer":0,"back":"答え：① are → is\nThere is a lot of water in this bottle.\nコツ：water は数えられない物 → is。a lot of がついても is のまま。\n（本冊440）"},{"id":"q14","category":"まちがい探し","front":"まちがっている言葉が1つあります。どれ？\nI ①prefer ②tea ③than ④coffee.","options":["①prefer","②tea","③than","④coffee"],"answer":2,"back":"答え：③ than → to\nI prefer tea to coffee.\nコツ：prefer は than ではなく to を使う。prefer tea to coffee ＝ コーヒーより紅茶が好き。\n（本冊415）"}]}];
